@Singleton
final class GroundLoot
{
    @Inject Client client;
    @Inject ImprovedLootingConfig config;
    @Inject FilterIcons filters;
    @Inject ItemIcons icons;
    @Inject PluginManager plugins;
    @Inject Notifier notifier;
    @Inject LootPreferences preferences;
    @Inject LootAlerts alerts;
    @Inject PriceTiers tiers;
    private final Map<TileItem, Entry> entries = new IdentityHashMap<>();
    private final Map<Tile, Map<Integer,Integer>> menuRanks = new IdentityHashMap<>();
    private final Set<Tile> beamTiles = Collections.newSetFromMap(new IdentityHashMap<>());
    private volatile FilterIcons.Prepared prepared;
    private volatile boolean running;
    private boolean groundAllowed;
    private boolean conditionalMenuHiding;
    private long sequence, preferencesRevision, lastTickNanos;
    private volatile List<LootRow> rows = Collections.emptyList();
    private List<Entry> ordered = Collections.emptyList();
    private long selected = -1;
    private int selectedUntil, localViewId=Integer.MIN_VALUE, accountType=-1, evaluationsRemaining;
    private volatile String status = "Ground display is off";
    static final int MAX_ITEMS = 4096;
    static final class Entry
    {
        final Tile tile;
        final TileItem item;
        ItemFacts facts;
        DisplayConfig display;
        DisplayConfig filterDisplay;
        BufferedImage image;
        RuneLiteObject beam;
        Color beamColor;
        long key, renderQuantity;
        int renderDespawn, renderSpawnTick;
        boolean grouped;
        int spawnTick, quantity, ownership, distance;
        boolean pendingDrop, warningArmed, warned;
        String source;
        Entry(Tile tile, TileItem item) { this.tile = tile; this.item = item; }
    }
    Collection<Entry> entries() { return ordered; }
    private Map<Integer,Integer> ranks(Tile tile) { return menuRanks.computeIfAbsent(tile,this::rankPile); }
    private Map<Integer,Integer> rankPile(Tile tile)
    {
        if(tile==null || tile.getGroundItems()==null)return Collections.emptyMap();
        List<Entry> pile=new ArrayList<>();
        for(TileItem item:tile.getGroundItems()) {
            Entry entry=new Entry(tile,item),cached=entries.get(item);
            entry.facts=filters.facts(tile,item);entry.display=resolved(tile,item);
            if(entry.display==null)return Collections.emptyMap();
            entry.source=cached==null?null:cached.source;
            pile.add(entry);
        }

        group(pile);
        return LootPileOrder.ranks(pile,this::labelHidden,config.priceSource());
    }
    int menuRank(Tile tile, int id, int fallback) { return ranks(tile).getOrDefault(id,fallback); }

    private boolean menuHidden(Tile tile, int id) {
        if(tile==null || tile.getGroundItems()==null)return false;
        boolean found=false;
        for(TileItem item:tile.getGroundItems())if(item.getId()==id) {
            Entry e=entries.get(item);
            if(e==null || e.facts==null || e.display==null || !menuHidden(e))return false;
            found=true;
        }
        return found;
    }
    boolean menuHidden(Entry e)
    {
        Boolean choice=preferences==null?null:preferences.hideMenu(e.item.getId());
        if(choice==null)choice=e.display.getHideMenu();
        return (choice==null?config.hideHiddenMenuItems():choice) && labelHidden(e);
    }
    private void updateMenu(MenuOpened event) {
        if(client.getGameState()!=GameState.LOGGED_IN)return;
        MenuEntry[] original=client.getMenu().getMenuEntries();

        for(MenuEntry e:original)if(e.getType()==MenuAction.WIDGET_TARGET_ON_GROUND_ITEM
            || e.getType()==MenuAction.ITEM_USE_ON_GROUND_ITEM)return;
        if((config.hideHiddenMenuItems() || conditionalMenuHiding) && !reveal()) {
            List<MenuEntry> visible=new ArrayList<>();
            for(MenuEntry e:original) {
                boolean hide=false;
                if(e.onClick()==null && e.getSubMenu()==null && !e.isForceLeftClick() && ordinaryGroundAction(e.getType())) {
                    WorldView view=client.getWorldView(e.getWorldViewId());
                    Tile[][][] tiles=view==null || view.getScene()==null?null:view.getScene().getTiles();
                    int plane=view==null?-1:view.getPlane(),x=e.getParam0(),y=e.getParam1();
                    if(tiles!=null && plane>=0 && plane<tiles.length && tiles[plane]!=null && x>=0 && x<tiles[plane].length
                        && tiles[plane][x]!=null && y>=0 && y<tiles[plane][x].length)hide=menuHidden(tiles[plane][x][y],e.getIdentifier());
                }
                if(!hide)visible.add(e);
            }
            if(visible.size()!=original.length) {
                MenuEntry[] next=visible.toArray(new MenuEntry[0]);client.getMenu().setMenuEntries(next);
                if(event!=null)event.setMenuEntries(next);
            }
        }
        LootPileOrder.opened(client,config,event,this::ranks);
    }
    private static boolean ordinaryGroundAction(MenuAction type) {
        return type==MenuAction.GROUND_ITEM_FIRST_OPTION || type==MenuAction.GROUND_ITEM_SECOND_OPTION
            || type==MenuAction.GROUND_ITEM_THIRD_OPTION || type==MenuAction.GROUND_ITEM_FOURTH_OPTION
            || type==MenuAction.GROUND_ITEM_FIFTH_OPTION || type==MenuAction.EXAMINE_ITEM_GROUND;
    }
    List<LootRow> rows() { return rows; }
    void select(long key) { selected = key; selectedUntil = client.getTickCount() + 17; }
    boolean selected(Entry e) { return e.key == selected && client.getTickCount() <= selectedUntil; }
    String explain(long key)
    {
        for (Entry e : entries.values()) if (e.key == key && prepared != null && e.facts != null)
            return LootResolution.explain(prepared, e.facts, e.display, preferences == null ? LootPreferences.Action.FILTER : preferences.action(e.item.getId(), e.source),
                e.source, LootResolution.secondsRemaining(e.item.getDespawnTime(), client.getTickCount()), config.priceSource()) + "\nFinal ground label: "+(labelHidden(e)?"hidden":"visible")+"\nAlt-click label override: "+(preferences==null?null:preferences.labelHidden(e.item.getId()))+"\nItem menu choice: "+LootMenuChoice.of(preferences==null?null:preferences.hideMenu(e.item.getId()))+"\nRule menu choice: "+LootMenuChoice.of(e.display.getHideMenu())+"\nOrdinary menu actions: "+(menuHidden(e)?"hidden (Alt reveals)":"kept")+"\nMinimum label value: "+config.minimumLabelValue()+" gp\nBeam on this tile: "+beamTiles.contains(e.tile) + (icons.find(e.item.getId())==null?"":"\nManual icon override: "+icons.find(e.item.getId()));
        return "This pile is no longer nearby. Refresh the browser.";
    }
    DisplayConfig resolved(Tile tile, TileItem item)
    {
        Entry entry = entries.get(item);
        if (entry != null && entry.facts != null && entry.display != null && entry.facts.getQuantity()==item.getQuantity() && entry.facts.getOwnership()==item.getOwnership()) return entry.display;
        FilterIcons.Prepared snapshot = filters.snapshot();
        return snapshot == null ? null : LootResolution.resolve(snapshot, filters.facts(tile, item), preferences, entry==null?null:entry.source);
    }
    String status() { return status; }
    boolean isRunning() { return running; }
    boolean groundAllowed() { return running && groundAllowed; }
    boolean reveal() { return client.isKeyPressed(KeyCode.KC_ALT); }
    boolean labelHidden(Entry e) {
        Boolean manual=preferences==null?null:preferences.labelHidden(e.item.getId());
        return LootDisplayOptions.ownershipHidden(config,e) || LootDisplayOptions.hidden(e.display.isHideOverlay(),manual,LootValues.value(config,e.facts,e.renderQuantity),LootDisplayOptions.minimum(config,e));
    }
    boolean locallyHidden(Entry e) {
        Boolean manual=preferences==null?null:preferences.labelHidden(e.item.getId());
        return LootDisplayOptions.ownershipHidden(config,e) || LootDisplayOptions.hidden(false,manual,LootValues.value(config,e.facts,e.renderQuantity),LootDisplayOptions.minimum(config,e));
    }
    double renderTick() { return client.getTickCount() + (lastTickNanos == 0 ? 0 : Math.min(1, (System.nanoTime()-lastTickNanos)/600000000.0)); }

    void refreshOverrides()
    {
        menuRanks.clear();
        if(!running || prepared==null)return;
        applyOverrides();
        publishRows();
        updateBeams();
    }
    private void applyOverrides()
    {
        preferencesRevision=preferences==null?0:preferences.revision();
        for(Entry e:entries.values())if(e.facts!=null && e.filterDisplay!=null)
            e.display=preferences==null?e.filterDisplay:LootPreferences.apply(e.filterDisplay,preferences.action(e.item.getId(),e.source));
    }
    void refreshSettings()
    {
        conditionalMenuHiding=false;
        menuRanks.clear();
        prepared=null;
        for(Entry e:entries.values()){e.facts=null;e.image=null;beamOff(e);}
        ordered=Collections.emptyList();rows=Collections.emptyList();
    }
    void clear()
    {
        conditionalMenuHiding=false;
        menuRanks.clear();
        for (Entry e : entries.values()) beamOff(e);
        entries.clear(); beamTiles.clear(); prepared = null; running = false; localViewId=Integer.MIN_VALUE; rows = Collections.emptyList(); ordered = Collections.emptyList(); selected = -1; if(alerts != null) alerts.clear();
    }
    private String competing()
    {
        List<String> names=new ArrayList<>();
        for (net.runelite.client.plugins.Plugin plugin : plugins.getPlugins()) {
            if (("Loot Filters".equals(plugin.getName()) || "Loot Filters TEST".equals(plugin.getName()) || "Ground Items".equals(plugin.getName())) && plugins.isPluginActive(plugin)) names.add(plugin.getName());
        }
        return String.join(", ",names);
    }
    @Subscribe public void onGameTick(GameTick event)
    {
        menuRanks.clear();
        evaluationsRemaining=256;
        lastTickNanos=System.nanoTime();
        if(alerts != null) alerts.tick();
        if (client.getGameState() != GameState.LOGGED_IN) { clear(); status="Log in to see nearby loot"; return; }
        groundAllowed = config.lootOverlay();
        FilterIcons.Prepared next = filters.snapshot();
        if (next == null) { refreshSettings(); status = "Waiting for a valid loot filter"; return; }
        boolean starting = !running;
        long overrideVersion = preferences == null ? 0 : preferences.revision();
        if (overrideVersion != preferencesRevision) applyOverrides();
        if (next != prepared) { for (Entry e : entries.values()) { e.facts = null; beamOff(e); } prepared = next; }
        int nextAccount=client.getVarbitValue(net.runelite.api.gameval.VarbitID.IRONMAN);
        if(accountType!=nextAccount){accountType=nextAccount;for(Entry e:entries.values())e.facts=null;}
        running = true;
        WorldView localView=client.getLocalPlayer()==null?null:client.getLocalPlayer().getWorldView();
        int nextView=localView==null?Integer.MIN_VALUE:localView.getId();
        if (starting || nextView!=localViewId) {
            seed(client.getTopLevelWorldView());
            if (localView != client.getTopLevelWorldView()) seed(localView);
            localViewId=nextView;
        }
        for (Entry e : entries.values())
        {
            update(e, false);
            if (e.pendingDrop && e.display != null && client.getTickCount() > e.spawnTick)
            { e.pendingDrop = false; if(alerts != null) alerts.drop(e, prepared); }
            if(alerts != null && config.despawnWarnings() && e.display != null) alerts.despawn(e, LootResolution.secondsRemaining(e.item.getDespawnTime(), client.getTickCount()));
        }
        publishRows();
        updateBeams();
        String overlap=groundAllowed?competing():"";
        status = (groundAllowed ? "Ground display on · " : "Ground display off · ") + entries.size() + " items tracked" + (entries.size() >= MAX_ITEMS ? " (tracking limit reached)" : "")
            + (overlap.isEmpty()?"":". Possible duplicate labels: "+overlap+" is also active.");
    }
    private void seed(WorldView view)
    {
        if (view == null || view.getScene() == null) return;
        if(view.getScene().getTiles() == null) return;
        for (Tile[][] plane : view.getScene().getTiles()) for (Tile[] row : plane) for (Tile tile : row) {
            if (tile != null && tile.getGroundItems() != null) for (TileItem item : tile.getGroundItems()) add(tile, item, false);
        }
    }
    private void add(Tile tile, TileItem item, boolean alert)
    {
        menuRanks.remove(tile);
        if (!running || entries.containsKey(item) || entries.size() >= MAX_ITEMS) return;
        Entry entry = new Entry(tile, item); entry.key = ++sequence; entry.spawnTick = client.getTickCount(); entry.pendingDrop = alert; entries.put(item, entry); update(entry, false);
    }
    @Subscribe public void onItemSpawned(ItemSpawned e) { add(e.getTile(), e.getItem(), true); }
    @Subscribe(priority=1) public void onMenuOpened(MenuOpened e) { menuRanks.clear(); updateMenu(e); }
    @Subscribe(priority=-10) public void onPostMenuSort(PostMenuSort e) { if(!client.isMenuOpen())updateMenu(null); }
    @Subscribe public void onItemDespawned(ItemDespawned e) { menuRanks.remove(e.getTile()); Entry old = entries.remove(e.getItem()); if (old != null) beamOff(old); }
    @Subscribe public void onItemQuantityChanged(ItemQuantityChanged e) { menuRanks.remove(e.getTile()); Entry old = entries.get(e.getItem()); if (old != null) {old.facts=null;update(old, false);} }
    @Subscribe public void onGameStateChanged(GameStateChanged e) { if (e.getGameState() != GameState.LOGGED_IN) clear(); }
    @Subscribe public void onWorldViewUnloaded(WorldViewUnloaded e)
    {
        menuRanks.clear();
        entries.values().removeIf(entry -> { if (entry.tile.getLocalLocation().getWorldView() == e.getWorldView().getId()) { beamOff(entry); return true; } return false; });
    }
    private void update(Entry e, boolean alert)
    {
        if (prepared == null) return;
        if(e.facts==null && evaluationsRemaining<=0)return;
        int quantity=e.item.getQuantity(), ownership=e.item.getOwnership();

        if(evaluationsRemaining>0 && (e.facts==null || e.quantity!=quantity || e.ownership!=ownership || (e.key & 63)==(client.getTickCount() & 63))) {
            evaluationsRemaining--;
            ItemFacts facts=filters.facts(e.tile,e.item);e.quantity=quantity;e.ownership=ownership;
            if(!facts.equals(e.facts)){
                e.facts=facts;e.filterDisplay=prepared.program.evaluate(facts);
                e.display=preferences==null?e.filterDisplay:LootPreferences.apply(e.filterDisplay,preferences.action(facts.getId(),e.source));
                e.image=itemImage(e);
            }
        }
        if(e.image==null && e.display.getIcon()!=null)e.image=itemImage(e);
        if(e.display!=null && explicitlyHidesMenu(e))conditionalMenuHiding=true;
    }
    private boolean explicitlyHidesMenu(Entry e){Boolean itemChoice=preferences==null?null:preferences.hideMenu(e.item.getId());return Boolean.TRUE.equals(itemChoice==null?e.display.getHideMenu():itemChoice);}
    private BufferedImage itemImage(Entry e)
    {
        ItemIcons.Assignment manual = icons.find(e.item.getId());
        return manual == null ? image(e.display.getIcon(), e.item.getId()) : icons.image(manual, e.item.getId());
    }
    private void group(List<Entry> pile)
    {
        Map<List<Object>, Entry> groups = new HashMap<>();boolean group=config.groupStacks();
        for(Entry e : pile)
        {
            e.grouped=false; e.renderQuantity=e.facts.getQuantity(); e.renderDespawn=e.item.getDespawnTime();e.renderSpawnTick=e.spawnTick;
            if(!group) continue;
            List<Object> key=Arrays.asList(e.tile,e.item.getId(),e.display,e.source,LootDisplayOptions.ownershipHidden(config,e));
            Entry lead=groups.putIfAbsent(key,e);
            if(lead!=null) {e.grouped=true;lead.renderQuantity+=e.renderQuantity;
                if(e.renderDespawn>0 && (lead.renderDespawn<=0 || e.renderDespawn<lead.renderDespawn)){lead.renderDespawn=e.renderDespawn;lead.renderSpawnTick=e.spawnTick;}}
        }
    }
    private void publishRows()
    {
        conditionalMenuHiding=false;
        List<Entry> nearby = new ArrayList<>();
        Player player=client.getLocalPlayer();LocalPoint point=player==null?null:player.getLocalLocation();WorldView view=player==null?null:player.getWorldView();
        int range=LootAlerts.clamp(config.labelRange(),1,64),world=view==null?Integer.MIN_VALUE:view.getId(),plane=view==null?-1:view.getPlane();
        for(Entry e:entries.values()) {
            if(e.facts!=null && e.display!=null && explicitlyHidesMenu(e))conditionalMenuHiding=true;
            LocalPoint at=e.tile.getLocalLocation();if(e.facts==null || point==null || at==null || at.getWorldView()!=world || e.tile.getPlane()!=plane)continue;
            e.distance=Math.max(Math.abs(point.getX()-at.getX()),Math.abs(point.getY()-at.getY()))/128;if(e.distance<=range)nearby.add(e); }
        Comparator<Entry> byName = Comparator.comparing(e -> e.facts.getName(), String.CASE_INSENSITIVE_ORDER);
        ImprovedLootingConfig.LabelOrder order = config.labelOrder();
        Comparator<Entry> sorting = order == ImprovedLootingConfig.LabelOrder.NAME ? byName
            : order == ImprovedLootingConfig.LabelOrder.DISTANCE ? Comparator.comparingInt(e -> e.distance)
            : order == ImprovedLootingConfig.LabelOrder.TIME ? Comparator.comparingInt(e -> e.item.getDespawnTime() <= 0 ? Integer.MAX_VALUE : e.item.getDespawnTime())
            : Comparator.<Entry>comparingLong(e -> LootValues.value(config,e.facts,e.facts.getQuantity())).reversed();
        nearby.sort(sorting.thenComparing(byName).thenComparingLong(e -> e.key)); ordered = nearby;
        group(nearby);
        if(config.groupStacks() && order==ImprovedLootingConfig.LabelOrder.VALUE)nearby.sort(Comparator.<Entry>comparingLong(e->LootValues.value(config,e.facts,e.renderQuantity)).reversed().thenComparing(byName).thenComparingLong(e->e.key));
        if(config.prioritizeLoot())nearby.sort(LootPileOrder.labels(this::labelHidden,config.priceSource()).thenComparing(byName).thenComparingLong(e->e.key));
        List<LootRow> next = new ArrayList<>();
        for (Entry e : nearby)
        {
            if(next.size() >= 512) break;
            next.add(new LootRow(e.key, e.item.getId(), e.facts.getQuantity(), LootValues.value(config,e.facts,e.facts.getQuantity()),
                e.distance, LootResolution.secondsRemaining(e.item.getDespawnTime(), client.getTickCount()), e.facts.getName(),
                preferences == null ? "" : preferences.category(e.item.getId()), e.source, null, labelHidden(e), e.image));
        }
        rows = Collections.unmodifiableList(next);
    }

    private BufferedImage image(BufferedImageProvider icon, int itemId)
    {
        if (icon == null) return null;
        if (icon instanceof BufferedImageProvider.File) return prepared.images.get(((BufferedImageProvider.File)icon).getFilename());
        if (icon instanceof BufferedImageProvider.CurrentItem) return icons.items.getImage(itemId);
        if (icon instanceof BufferedImageProvider.Item) { int id = ((BufferedImageProvider.Item)icon).getItemId(); return id < client.getItemCount() ? icons.items.getImage(id) : null; }
        BufferedImageProvider.Sprite sprite = (BufferedImageProvider.Sprite)icon;
        if (sprite.getSpriteId() == 9000000) return null;
        try { return icons.sprites.getSprite(sprite.getSpriteId(), sprite.getIndex()); } catch (IndexOutOfBoundsException ex) { return null; }
    }
    static Color beamColor(DisplayConfig display,long value,PriceTiers.Setup setup)
    {
        if(display==null || display.isHidden())return null;
        if(display.isShowLootbeam()){Color color=display.getLootbeamColor();return color==null?display.getTextColor():color;}
        if(display.isHideOverlay() || setup==null)return null;
        PriceTiers.Tier tier=setup.tiers[PriceTiers.index(setup,value)];return tier.lootBeam?new Color(tier.color):null;
    }
    private void updateBeams()
    {
        Map<Entry,Color> desired=new LinkedHashMap<>();
        if(groundAllowed && config.lootBeams()){
            PriceTiers.Ready ready=tiers==null?null:tiers.snapshot();PriceTiers.Setup setup=ready==null?null:ready.setup;
            List<Entry> candidates=new ArrayList<>();
            for(Entry e:ordered)if(!e.grouped && !locallyHidden(e) && inRange(e,24) && beamColor(e.display,LootValues.value(config,e.facts,e.renderQuantity),setup)!=null)candidates.add(e);
            candidates.sort(Comparator.<Entry>comparingLong(e->LootValues.value(config,e.facts,e.renderQuantity)).reversed().thenComparingLong(e->e.key));
            Set<Tile> selected=Collections.newSetFromMap(new IdentityHashMap<>());
            for(Entry e:candidates){if(selected.add(e.tile)){desired.put(e,beamColor(e.display,LootValues.value(config,e.facts,e.renderQuantity),setup));if(desired.size()==64)break;}}
        }

        for(Entry e:entries.values())if(!desired.containsKey(e) || !Objects.equals(e.beamColor,desired.get(e)))beamOff(e);
        desired.forEach(this::updateBeam);
    }
    private void updateBeam(Entry e,Color color)
    {
        if(e.beam!=null || beamTiles.size()>=64 || beamTiles.contains(e.tile))return;
        ModelData data = client.loadModelData(43330);
        if (data == null) return;
        short hsl = JagexColor.rgbToHSL(color.getRGB(), 1);
        int h = JagexColor.unpackHue(hsl), s = JagexColor.unpackSaturation(hsl), l = JagexColor.unpackLuminance(hsl);
        Model model = data.cloneVertices().cloneColors()
            .recolor(JagexColor.packHSL(25, 6, 64), JagexColor.packHSL(h, Math.max(0, s - 1), l))
            .recolor(JagexColor.packHSL(25, 7, 88), JagexColor.packHSL(h, s, Math.min(l + 24, JagexColor.LUMINANCE_MAX)))
            .light(75 + ModelData.DEFAULT_AMBIENT, 1875 + ModelData.DEFAULT_CONTRAST, ModelData.DEFAULT_X, ModelData.DEFAULT_Y, ModelData.DEFAULT_Z);
        e.beam = new RuneLiteObject(client); e.beam.setModel(model); e.beam.setLocation(e.tile.getLocalLocation(), e.tile.getPlane());
        e.beam.setAnimation(client.loadAnimation(net.runelite.api.gameval.AnimationID.FX_BEAM_IDLE)); e.beam.setActive(true); e.beamColor = color; beamTiles.add(e.tile);
    }
    private void beamOff(Entry e) { if (e.beam != null) { e.beam.setActive(false); beamTiles.remove(e.tile); } e.beam = null; e.beamColor = null; }
    boolean inRange(Entry e, int distance)
    {
        Player player = client.getLocalPlayer(); if (player == null || player.getWorldView() == null || player.getLocalLocation() == null || e.tile.getLocalLocation() == null || player.getWorldView().getId() != e.tile.getLocalLocation().getWorldView() || player.getWorldView().getPlane() != e.tile.getPlane()) return false;
        LocalPoint a = player.getLocalLocation(), b = e.tile.getLocalLocation();
        return Math.abs(a.getX() - b.getX()) <= distance * 128 && Math.abs(a.getY() - b.getY()) <= distance * 128;
    }
}

package com.improvedlooting;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Tile;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.AsyncBufferedImage;

final class GroundLootCards
{
    @Inject Client client;
    @Inject ClientThread thread;
    @Inject GroundLoot loot;
    @Inject ImprovedLootingConfig config;
    @Inject PriceTiers tiers;
    @Inject LootLabelInput input;
    private final Map<List<Object>,BufferedImage> images=new LinkedHashMap<List<Object>,BufferedImage>(128,.75f,true){protected boolean removeEldestEntry(Map.Entry<List<Object>,BufferedImage> e){return size()>512;}};
    private final Map<BufferedImage,Boolean> ready=new LinkedHashMap<>();
    private final PriceTiers.Setup defaultTiers=PriceTiers.defaults();
    private Tile expanded;
    private Rectangle expandedBounds;
    private long generation;
    void clear(){generation++;images.clear();ready.clear();expanded=null;expandedBounds=null;}
    BufferedImage image(GroundLoot.Entry entry,int size,double fraction)
    {
        BufferedImage source=entry.image!=null?entry.image:loot.icons.items.getImage(entry.item.getId());if(source==null)return null;
        if(source instanceof AsyncBufferedImage && !ready.containsKey(source)){
            if(ready.size()>=GroundLoot.MAX_ITEMS)ready.remove(ready.keySet().iterator().next());ready.put(source,false);long token=generation;
            ((AsyncBufferedImage)source).onLoaded(()->thread.invokeLater(()->{if(token==generation&&ready.containsKey(source))ready.put(source,true);}));
        }
        int step=(int)Math.round(Math.max(0,Math.min(1,fraction))*80);List<Object> key=Arrays.asList(source,size,step,config.originalImages());
        BufferedImage cached=images.get(key);if(cached!=null)return cached;
        BufferedImage copy=LootCardPainter.icon(source,size,step/80.0,config.originalImages());
        if(!(source instanceof AsyncBufferedImage)||Boolean.TRUE.equals(ready.get(source)))images.put(key,copy);
        return copy;
    }
    void render(Graphics2D original)
    {
        Graphics2D g=(Graphics2D)original.create();
        try{
            Rectangle viewport=new Rectangle(client.getViewportXOffset()+3,client.getViewportYOffset()+3,client.getViewportWidth()-6,client.getViewportHeight()-6);if(viewport.width<120||viewport.height<20)return;g.clip(viewport);
            ImprovedLootingConfig.CardTheme theme=config.cardTheme();Color backgroundColor=config.cardBackgroundColor();
            Font plain=LootCardPainter.font(theme,config.labelFontSize(),false),bold=LootCardPainter.font(theme,config.labelFontSize(),true);g.setFont(plain);
            int height=Math.max(LootCardPainter.height(theme,g.getFontMetrics(plain),config.cardHeight()),LootCardPainter.height(theme,g.getFontMetrics(bold),config.cardHeight()));
            int size=LootCardPainter.iconSize(height),pitch=height+LootAlerts.clamp(config.labelSpacing(),0,16);
            int limit=LootAlerts.clamp(config.cardRows(),0,20),maximum=LootAlerts.clamp(config.maxLabels(),10,1000),drawn=0,overflow=0;
            Map<Tile,List<GroundLoot.Entry>> piles=new LinkedHashMap<>();boolean reveal=loot.reveal();
            for(GroundLoot.Entry e:loot.entries())if(!e.grouped&&e.facts!=null&&e.display!=null&&(!loot.labelHidden(e)||reveal))piles.computeIfAbsent(e.tile,k->new ArrayList<>()).add(e);
            net.runelite.api.Point mouse=client.getMouseCanvasPosition();Point pointer=mouse==null?new Point(-1,-1):new Point(mouse.getX(),mouse.getY());
            Tile previous=expanded;Rectangle previousBounds=expandedBounds;expanded=null;expandedBounds=null;
            List<Rectangle> occupied=new ArrayList<>();PriceTiers.Ready setup=tiers==null?null:tiers.snapshot();PriceTiers.Setup selected=setup==null?defaultTiers:setup.setup;double now=loot.renderTick();
            for(List<GroundLoot.Entry> entries:piles.values())for(GroundLoot.Entry e:entries)if(loot.selected(e)||e.display.isHighlightTile()){
                Polygon poly=Perspective.getCanvasTilePoly(client,e.tile.getLocalLocation());if(poly!=null){if(e.display.getTileFillColor()!=null){g.setColor(e.display.getTileFillColor());g.fill(poly);}g.setColor(loot.selected(e)?Color.CYAN:e.display.getTileStrokeColor());g.draw(poly);}break;
            }
            for(Map.Entry<Tile,List<GroundLoot.Entry>> pile:piles.entrySet()){
                Tile tile=pile.getKey();List<GroundLoot.Entry> entries=pile.getValue();
                int width=LootAlerts.clamp(config.cardWidth(),120,2048);
                if(config.cardAutoWidth() || config.lootCompact()){
                    width=config.lootCompact()?48:120;
                    for(GroundLoot.Entry e:entries){long value=LootValues.value(config,e.facts,e.renderQuantity);PriceTiers.Tier tier=selected.tiers[PriceTiers.index(selected,value)];
                        width=Math.max(width,LootCardPainter.width(g.getFontMetrics(tier.bold?bold:plain),size,config.lootCompact()?"":e.facts.getName(),e.renderQuantity,LootDisplayOptions.price(config,e),config.cardShortPrices(),seconds(e)));}
                }
                width=Math.min(viewport.width,width);
                net.runelite.api.Point anchor=Perspective.getCanvasTextLocation(client,g,tile.getLocalLocation(),"",(tile.getItemLayer()==null?0:tile.getItemLayer().getHeight())+16);if(anchor==null)continue;
                int layoutX=anchor.getX()+(config.labelAlignment()==ImprovedLootingConfig.LabelAlignment.LEFT?width/2:config.labelAlignment()==ImprovedLootingConfig.LabelAlignment.RIGHT?-width/2:0);
                int baseCount=limit==0?entries.size():Math.min(limit,entries.size());int fit=Math.max(1,viewport.height/pitch-1);baseCount=Math.min(baseCount,fit);
                int baseHeight=baseCount*pitch-(pitch-height)+(entries.size()>baseCount?pitch:0);
                Rectangle collapsed=LootCardPainter.place(layoutX,anchor.getY(),width,baseHeight,viewport,occupied);
                if(collapsed==null){overflow+=entries.size();continue;}
                boolean hover=collapsed.contains(pointer)||(tile==previous&&previousBounds!=null&&previousBounds.contains(pointer));
                int count=Math.min(Math.min(hover?entries.size():baseCount,fit),Math.max(0,maximum-drawn));if(count==0){overflow+=entries.size();continue;}
                Rectangle box=LootCardPainter.place(layoutX,anchor.getY(),width,count*pitch-(pitch-height)+(entries.size()>count?pitch:0),viewport,occupied);
                if(box==null){count=Math.min(baseCount,maximum-drawn);box=collapsed;}occupied.add(box);
                if(hover){expanded=tile;expandedBounds=box.union(collapsed);}
                if(Math.abs(box.x+width/2-anchor.getX())>10 || Math.abs(box.y+box.height-anchor.getY())>12){g.setColor(new Color(180,190,200,90));g.drawLine(box.x+width/2,box.y+box.height,anchor.getX(),anchor.getY());}
                for(int i=0;i<count;i++){
                    GroundLoot.Entry e=entries.get(i);long value=LootValues.value(config,e.facts,e.renderQuantity);
                    PriceTiers.Tier tier=selected.tiers[PriceTiers.index(selected,value)];g.setFont(tier.bold?bold:plain);
                    int rowWidth=width;
                    if(config.cardIndividualWidth() && (config.cardAutoWidth() || config.lootCompact()))rowWidth=Math.min(width,Math.max(config.lootCompact()?48:120,
                        LootCardPainter.width(g.getFontMetrics(),size,config.lootCompact()?"":e.facts.getName(),e.renderQuantity,LootDisplayOptions.price(config,e),config.cardShortPrices(),seconds(e))));
                    Rectangle row=rowBounds(box,i*pitch,rowWidth,height,config.labelAlignment());
                    Paint rail=LootDisplayOptions.color(config,e,new Color(tier.color));
                    if(LootDisplayOptions.tierEffects(config,e)&&setup!=null){Paint effect=LootTextPaint.paint(tier,selected.seconds,System.nanoTime(),row.x,Math.max(80,width));if(effect!=null)rail=effect;}
                    double fraction=config.iconDespawnFade()?LootCardPainter.remaining(e.renderSpawnTick,e.renderDespawn,now):1;
                    LootCardPainter.row(g,row,rail,image(e,size,fraction),config.lootCompact()?"":e.facts.getName(),e.renderQuantity,LootDisplayOptions.price(config,e),loot.labelHidden(e),config.cardBackground(),config.cardBorder(),config.cardOpacity(),config.cardShortPrices(),seconds(e),theme,backgroundColor,config.railDespawnTimer()?LootCardPainter.remaining(e.renderSpawnTick,e.renderDespawn,now):1);
                    if(input!=null)input.add(row,e,loot.labelHidden(e));
                }
                g.setFont(plain);
                drawn+=count;
                if(entries.size()>count)footer(g,new Rectangle(box.x,box.y+count*pitch,width,height),"+ "+(entries.size()-count)+" more"+(hover?" · Nearby loot":" · hover to expand"));
            }
            if(overflow>0){String text=overflow+" more items · Nearby loot";int summaryWidth=Math.min(viewport.width-8,g.getFontMetrics().stringWidth(text)+16);Rectangle summary=LootCardPainter.place(viewport.x+summaryWidth/2+4,viewport.y+height+4,summaryWidth,height,viewport,occupied);if(summary!=null)footer(g,summary,text);}
        }finally{g.dispose();}
    }
    static Rectangle rowBounds(Rectangle pile,int y,int width,int height,ImprovedLootingConfig.LabelAlignment alignment) {
        int offset=alignment==ImprovedLootingConfig.LabelAlignment.LEFT?0:alignment==ImprovedLootingConfig.LabelAlignment.RIGHT?pile.width-width:(pile.width-width)/2;
        return new Rectangle(pile.x+offset,pile.y+y,width,height);
    }
    private int seconds(GroundLoot.Entry entry)
    {
        return LootDisplayOptions.seconds(config,entry,client.getTickCount());
    }
    private void footer(Graphics2D g,Rectangle box,String text)
    {
        LootCardPainter.surface(g,box,config.cardBackground(),config.cardBorder(),config.cardOpacity(),config.cardTheme(),config.cardBackgroundColor());g.setColor(LootCardPainter.VALUE);
        text=LootCardPainter.fit(text,g.getFontMetrics(),box.width-16);
        int x=box.x+(box.width-g.getFontMetrics().stringWidth(text))/2,y=box.y+(box.height-g.getFontMetrics().getHeight())/2+g.getFontMetrics().getAscent();
        if(config.cardTheme()==ImprovedLootingConfig.CardTheme.OSRS){g.setColor(Color.BLACK);g.drawString(text,x+1,y+1);g.setColor(LootCardPainter.VALUE);}
        g.drawString(text,x,y);
    }
}

package com.improvedlooting;

import com.improvedlooting.rs2f.DisplayConfig;
import com.improvedlooting.rs2f.util.TextComponent;
import java.awt.*;
import java.util.*;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Tile;
import net.runelite.client.ui.overlay.*;

final class GroundLootOverlay extends Overlay
{
    private final GroundLoot loot;
    private final Client client;
    private final ImprovedLootingConfig config;
    @Inject private PriceTiers tiers;
    @Inject private GroundLootCards groundCards;
    @Inject private LootLabelInput input;
    void clear() { groundCards.clear();if(input!=null)input.reset(); }
    @Inject GroundLootOverlay(GroundLoot loot, Client client, ImprovedLootingConfig config)
    {
        this.loot = loot; this.client = client; this.config = config;
        setPosition(OverlayPosition.DYNAMIC); setLayer(OverlayLayer.ABOVE_SCENE);
    }
    @Override public Dimension render(Graphics2D original)
    {
        if(input!=null)input.beginFrame();
        if (!loot.groundAllowed()) { if(input!=null)input.reset();return null; }
        if (config.groundStyle() == ImprovedLootingConfig.GroundStyle.CARDS) {
            try { groundCards.render(original); }
            finally { finishInput(); }
            return null;
        }
        Graphics2D g = (Graphics2D)original.create();
        PriceTiers.Ready tierSetup=tiers!=null?tiers.snapshot():null;
        long animationTime=System.nanoTime();
        try {
            g.clipRect(client.getViewportXOffset(), client.getViewportYOffset(), client.getViewportWidth(), client.getViewportHeight());
            Map<Tile, Integer> offsets = new IdentityHashMap<>();
            Set<Tile> highlighted = Collections.newSetFromMap(new IdentityHashMap<>());
            int count = 0;
            java.util.List<GroundLoot.Entry> paintOrder = new ArrayList<>();
            for (GroundLoot.Entry entry : loot.entries()) {
                if (entry.grouped || entry.display == null || !loot.inRange(entry, LootAlerts.clamp(config.labelRange(),1,64))
                    || entry.tile.getItemLayer() == null || loot.labelHidden(entry) && !loot.reveal()) continue;
                if (paintOrder.size() >= LootAlerts.clamp(config.maxLabels(),10,1000)) break;
                paintOrder.add(entry);
            }

            if (config.prioritizeLoot()) Collections.reverse(paintOrder);
            for (GroundLoot.Entry entry : paintOrder) {
                if (loot.selected(entry)) {
                    Polygon poly=Perspective.getCanvasTilePoly(client,entry.tile.getLocalLocation());
                    if(poly!=null){g.setColor(new Color(80,220,255,50));g.fill(poly);g.setColor(Color.CYAN);g.draw(poly);}
                }
                if (count >= LootAlerts.clamp(config.maxLabels(),10,1000)) continue;
                DisplayConfig display = entry.display;
                if (entry.grouped || display == null || !loot.inRange(entry, LootAlerts.clamp(config.labelRange(),1,64)) || entry.tile.getItemLayer() == null || loot.labelHidden(entry) && !loot.reveal()) continue;
                if (display.isHighlightTile() && highlighted.add(entry.tile)) {
                    Polygon poly = Perspective.getCanvasTilePoly(client, entry.tile.getLocalLocation());
                    if (poly != null) {
                        if (display.getTileFillColor() != null) { g.setColor(display.getTileFillColor()); g.fill(poly); }
                        g.setColor(display.getTileStrokeColor()); g.draw(poly);
                    }
                }
                g.setFont(config.labelFontSize()==0?display.getFont():display.getFont().deriveFont((float)LootAlerts.clamp(config.labelFontSize(),8,32)));
                PriceTiers.Tier tier=tierSetup==null?null:tierSetup.setup.tiers[PriceTiers.index(tierSetup.setup,LootValues.value(config,entry.facts,entry.renderQuantity))];
                if(tier!=null && tier.bold)g.setFont(g.getFont().deriveFont(g.getFont().getStyle()|Font.BOLD));
                String text = entry.facts.getName();
                text += LootCardPainter.quantity(entry.renderQuantity);
                String details=LootCardPainter.details(LootDisplayOptions.price(config,entry),config.cardShortPrices(),LootDisplayOptions.seconds(config,entry,client.getTickCount()));
                if(!details.isEmpty())text+=" "+details;
                boolean compact = config.lootCompact();
                if (compact) text = LootCardPainter.quantity(entry.renderQuantity).trim();
                FontMetrics metrics = g.getFontMetrics();
                java.awt.image.BufferedImage image = compact ? lootItemImage(entry) : entry.image;
                int maxIcon=LootAlerts.clamp(config.iconSize(),12,96);
                if(image!=null && config.iconDespawnFade())image=groundCards.image(entry,maxIcon,LootCardPainter.remaining(entry.renderSpawnTick,entry.renderDespawn,loot.renderTick()));
                int iw=0,ih=0;
                if(image!=null){double scale=Math.min((double)maxIcon/image.getWidth(),(double)maxIcon/image.getHeight());if(config.originalImages())scale=Math.min(1,scale);iw=Math.max(1,(int)(image.getWidth()*scale));ih=Math.max(1,(int)(image.getHeight()*scale));}
                int iconWidth = image==null?0:iw+3;
                int height = Math.max(metrics.getHeight(), ih) + 4;
                int width = Math.max(12, metrics.stringWidth(text) + iconWidth + 6);
                net.runelite.api.Point location = Perspective.getCanvasTextLocation(client, g, entry.tile.getLocalLocation(), "", entry.tile.getItemLayer().getHeight() + 20);
                if (location == null) continue;
                int offset = offsets.getOrDefault(entry.tile, 0);
                int x = location.getX() - (config.labelAlignment()==ImprovedLootingConfig.LabelAlignment.LEFT?0:config.labelAlignment()==ImprovedLootingConfig.LabelAlignment.RIGHT?width:width/2), y = location.getY() - offset - height;
                if (y < client.getViewportYOffset() || x < client.getViewportXOffset() || x + width > client.getViewportXOffset() + client.getViewportWidth()) continue;
                count++; offsets.put(entry.tile, offset + height + LootAlerts.clamp(config.labelSpacing(),0,16));
                if (display.getBackgroundColor() != null) { g.setColor(display.getBackgroundColor()); g.fillRect(x, y, width, height); }
                if (display.getBorderColor() != null) { g.setColor(display.getBorderColor()); g.drawRect(x, y, width, height); }
                if (image != null) g.drawImage(image, x + 2, y + (height - ih) / 2, iw, ih, null);
                if(input!=null)input.add(new Rectangle(x,y,width,height),entry,loot.labelHidden(entry));
                Color color=LootDisplayOptions.color(config,entry,tier==null?Color.WHITE:new Color(tier.color));
                TextComponent label = new TextComponent(); label.setText(text); label.setColor(loot.labelHidden(entry) ? Color.GRAY : color);
                if(tier!=null && LootDisplayOptions.tierEffects(config,entry) && !loot.labelHidden(entry)) {
                    label.setForegroundPaint(LootTextPaint.paint(tier,tierSetup.setup.seconds,animationTime,x+iconWidth+3,metrics.stringWidth(text)));
                }
                if (display.getTextAccent() != null) label.setTextAccent(display.getTextAccent());
                if (display.getTextAccentColor() != null) label.setAccentColor(display.getTextAccentColor());
                label.setPosition(new Point(x + iconWidth + 3, y + (height - metrics.getHeight()) / 2 + metrics.getAscent())); label.render(g);
            }
        } finally { g.dispose();finishInput(); }
        return null;
    }
    private void finishInput(){if(input!=null){if(client.isMenuOpen())input.reset();else input.finishFrame();}}
    private java.awt.image.BufferedImage lootItemImage(GroundLoot.Entry entry) { return loot.icons.items.getImage(entry.item.getId()); }
}

package com.improvedlooting;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.*;
import java.util.*;
import javax.imageio.*;
import javax.imageio.stream.MemoryCacheImageInputStream;
import net.runelite.client.util.Filepath;
final class IconImages {
 static String read(Filepath path) throws IOException {
  try(InputStream in=path.openInputStream()) {
   byte[] data=in.readNBytes(2097153);
   if(data.length>2097152) throw new IllegalArgumentException("Image exceeds 2 MB: "+path.getFileName());
   return encode(normalize(data));
  }
 }
 static BufferedImage normalize(byte[] data) throws IOException {
  try(MemoryCacheImageInputStream in=new MemoryCacheImageInputStream(new ByteArrayInputStream(data))) {
   Iterator<ImageReader> readers=ImageIO.getImageReaders(in);
   if(!readers.hasNext()) throw new IllegalArgumentException("Unsupported image. Use PNG, JPEG or GIF.");
   ImageReader r=readers.next();
   try {
    String format=r.getFormatName(); if(!format.equalsIgnoreCase("png") && !format.equalsIgnoreCase("jpeg") && !format.equalsIgnoreCase("gif")) throw new IllegalArgumentException("Use PNG, JPEG or GIF.");
    r.setInput(in); int w=r.getWidth(0),h=r.getHeight(0);
    if(w<1 || h<1 || w>2048 || h>2048 || (long)w*h>4194304) throw new IllegalArgumentException("Image dimensions exceed 2048 x 2048.");
    BufferedImage source=r.read(0),result=new BufferedImage(w,h,BufferedImage.TYPE_INT_ARGB);
    Graphics2D g=result.createGraphics();
    try { g.drawImage(source,0,0,null); } finally { g.dispose(); }
    return result;
   } finally { r.dispose(); }
  }
 }
 static String encode(BufferedImage image) throws IOException { ByteArrayOutputStream out=new ByteArrayOutputStream(); ImageIO.write(image,"png",out); return Base64.getEncoder().encodeToString(out.toByteArray()); }
 static BufferedImage decode(String value) { try { if(value==null || value.length()>2800000) throw new IllegalArgumentException("Invalid saved icon"); return normalize(Base64.getDecoder().decode(value)); } catch(IOException e) { throw new IllegalArgumentException("Invalid saved icon",e); } }
 static String safeName(String name) {
  if(name==null || name.length()>240 || name.isBlank() || name.chars().anyMatch(Character::isISOControl) || name.startsWith("/") || name.startsWith("\\") || name.contains(":")) throw new IllegalArgumentException("Invalid image filename");
  String normalized=name.replace('\\','/');
  for(String part:normalized.split("/",-1)) if(part.equals("..") || part.equals(".") || part.isEmpty()) throw new IllegalArgumentException("Image filename must stay inside the selected icon folder");
  return normalized;
 }
}

package com.improvedlooting;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.Map;
import javax.swing.*;

final class IconPalette extends JPanel
{
    static final class Selection
    {
        final ItemIcons.Kind kind;
        final int item;
        final String file, image;
        Selection(ItemIcons.Kind kind,int item,String file,String image) { this.kind=kind; this.item=item; this.file=file; this.image=image; }
        String expression() {
            if(kind==ItemIcons.Kind.CURRENT_ITEM) return "CurrentItem()";
            if(kind==ItemIcons.Kind.ITEM) return "Item("+item+")";
            if(kind==null) return null;
            return "File(\""+file.replace("\\","\\\\").replace("\"","\\\"")+"\")";
        }
    }
    private Selection selected=new Selection(ItemIcons.Kind.CURRENT_ITEM,0,null,null);
    private final JLabel summary=new JLabel("Selected: this item's picture");
    private final ButtonGroup group=new ButtonGroup();
    private final ItemPicker itemPicker;
    private final JToggleButton current;
    private final JToggleButton itemChoice=new JToggleButton("Choose an item picture below");
    private boolean closed;

    IconPalette(ItemIcons icons,Map<String,String> images) { this(icons,images,true); }
    IconPalette(ItemIcons icons,Map<String,String> images,boolean allowHidden)
    {
        super(new BorderLayout(4,4));
        JTabbedPane tabs=new JTabbedPane();
        JPanel common=new JPanel(new GridLayout(0,4,6,6));
        current=tile(common,"This item",null,selected); current.setSelected(true);
        if(allowHidden) tile(common,"Hidden",hiddenImage(),new Selection(null,0,null,null));
        for(ItemIcons.Kind kind:new ItemIcons.Kind[]{ItemIcons.Kind.HEART,ItemIcons.Kind.STAR,ItemIcons.Kind.DIAMOND}) {
            ItemIcons.Assignment assignment=new ItemIcons.Assignment(); assignment.kind=kind;
            BufferedImage image=icons.image(assignment,0);
            String encoded;
            try { encoded=IconImages.encode(image); } catch(IOException ex) { throw new IllegalArgumentException("Could not prepare icon",ex); }
            String name=kind.name().substring(0,1)+kind.name().substring(1).toLowerCase(java.util.Locale.ROOT);

            String file="improved-icons/"+kind.name().toLowerCase(java.util.Locale.ROOT)+"-"+Integer.toHexString(encoded.hashCode())+".png";
            tile(common,name,image,new Selection(kind,0,file,encoded));
        }
        JPanel commonTop=new JPanel(new BorderLayout()); commonTop.add(common,BorderLayout.NORTH); tabs.addTab("Symbols",commonTop);
        if(!images.isEmpty()) {
            JPanel imported=new JPanel(new GridLayout(0,4,6,6));
            images.forEach((name,encoded) -> tile(imported,name,IconImages.decode(encoded),new Selection(ItemIcons.Kind.IMAGE,0,name,encoded)));
            JScrollPane scroll=new JScrollPane(imported); scroll.setPreferredSize(new Dimension(360,170)); tabs.addTab("Filter images",scroll);
        }
        itemPicker=new ItemPicker(icons.search,3);
        JPanel picture=new JPanel(new BorderLayout(4,4)); picture.add(itemPicker,BorderLayout.CENTER); picture.add(itemChoice,BorderLayout.SOUTH);
        group.add(itemChoice); itemChoice.setEnabled(false);
        itemPicker.onSelect(choice -> {
            itemChoice.setEnabled(choice!=null);
            if(choice!=null) {
                selected=new Selection(ItemIcons.Kind.ITEM,choice.id,null,null); itemChoice.setSelected(true);
                itemChoice.setText(choice.name); itemChoice.setIcon(new Thumbnail(choice.image)); summary.setIcon(null); summary.setText("Selected: "+choice.name);
                if(choice.image instanceof net.runelite.client.util.AsyncBufferedImage)
                    ((net.runelite.client.util.AsyncBufferedImage)choice.image).onLoaded(() -> SwingUtilities.invokeLater(() -> { if(!closed) itemChoice.repaint(); }));
            }
        });
        itemChoice.addActionListener(e -> { ItemSearch.Choice choice=itemPicker.selected(); if(choice!=null) { selected=new Selection(ItemIcons.Kind.ITEM,choice.id,null,null); summary.setText("Selected: "+choice.name); } });
        tabs.addTab("Item pictures",picture);
        add(tabs,BorderLayout.CENTER);
        JPanel footer=new JPanel(new BorderLayout(4,4)); footer.add(summary,BorderLayout.NORTH);
        JButton upload=new JButton("Add image file…"); footer.add(upload,BorderLayout.SOUTH);
        upload.addActionListener(e -> {
            java.util.List<net.runelite.client.util.Filepath> files=new net.runelite.client.util.Filepath.Chooser().setIsOpen().setAcceptsFiles().addExtensionFilter("Images","png","jpg","jpeg","gif").showDialog(this);
            if(files.isEmpty()) return;
            upload.setEnabled(false);
            new SwingWorker<String,Void>() {
                protected String doInBackground() throws Exception { return IconImages.read(files.get(0)); }
                protected void done() {
                    if(closed) return;
                    upload.setEnabled(true);
                    try {
                        String encoded=get();
                        selected=new Selection(ItemIcons.Kind.IMAGE,0,"improved-icons/upload-"+Integer.toHexString(encoded.hashCode())+".png",encoded);
                        group.clearSelection(); summary.setText("Selected: uploaded image"); summary.setIcon(new Thumbnail(IconImages.decode(encoded)));
                    } catch(Exception ex) { summary.setText("Image not loaded: "+(ex.getCause()==null?ex.getMessage():ex.getCause().getMessage())); }
                }
            }.execute();
        });
        add(footer,BorderLayout.SOUTH);
    }
    private JToggleButton tile(JPanel panel,String name,BufferedImage image,Selection selection)
    {
        String label=name.length()>15?name.substring(0,12)+"…":name;
        JToggleButton button=new JToggleButton(label,new Thumbnail(image)); button.setToolTipText(name);
        button.setHorizontalTextPosition(SwingConstants.CENTER); button.setVerticalTextPosition(SwingConstants.BOTTOM);
        button.setPreferredSize(new Dimension(100,64)); button.setMargin(new Insets(4,3,4,3));
        group.add(button); panel.add(button);
        button.addActionListener(e -> { selected=selection; summary.setIcon(null); summary.setText("Selected: "+name); }); return button;
    }
    void currentItem(ItemSearch.Choice choice) {
        current.setIcon(new Thumbnail(choice==null?null:choice.image)); current.setToolTipText(choice==null?"The matching item's own picture":choice.name);
        if(choice!=null && choice.image instanceof net.runelite.client.util.AsyncBufferedImage)
            ((net.runelite.client.util.AsyncBufferedImage)choice.image).onLoaded(() -> SwingUtilities.invokeLater(() -> { if(!closed) current.repaint(); }));
    }
    Selection selection() { return selected; }
    void close() { closed=true; itemPicker.close(); }
    static final class Thumbnail implements Icon
    {
        private final BufferedImage image;
        Thumbnail(BufferedImage image) { this.image=image; }
        public int getIconWidth() { return 32; }
        public int getIconHeight() { return 32; }
        public void paintIcon(Component c,Graphics g,int x,int y) {
            if(image==null) { g.setColor(Color.GRAY); g.drawRect(x+7,y+7,18,18); g.drawString("?",x+12,y+21); return; }
            double scale=Math.min(32d/image.getWidth(),32d/image.getHeight());
            int width=(int)(image.getWidth()*scale),height=(int)(image.getHeight()*scale);
            g.drawImage(image,x+(32-width)/2,y+(32-height)/2,width,height,c);
        }
    }
    private static BufferedImage hiddenImage()
    {
        BufferedImage image=new BufferedImage(32,32,BufferedImage.TYPE_INT_ARGB); Graphics2D g=image.createGraphics();
        try { g.setColor(new Color(220,85,85)); g.setStroke(new BasicStroke(3)); g.drawOval(4,4,23,23); g.drawLine(7,25,25,7); } finally { g.dispose(); } return image;
    }
}

