            control.setText(String.format(Locale.ROOT,"Choose: #%06X",color.getRGB()&0xffffff));control.setBackground(color);
            control.setForeground(color.getRed()*299+color.getGreen()*587+color.getBlue()*114>145000?Color.BLACK:Color.WHITE);
        });
        control.addActionListener(e->{
            Object profile=icons.configs.getProfile();Color before=config.untradeableColor();
            Color chosen=JColorChooser.showDialog(this,"Untradeable color",before==null?new Color(0xff5555):before);
            if(chosen!=null&&!closed&&Objects.equals(profile,icons.configs.getProfile())&&Objects.equals(before,config.untradeableColor()))
                icons.configs.setConfiguration(ImprovedLootingConfig.GROUP,"untradeableColor",new Color(chosen.getRGB()));
        });
    }
    private JButton backgroundColor(JPanel parent,ImprovedLootingConfig config)
    {
        parent.add(new JLabel("Background color"));JButton control=new JButton();parent.add(control);control.setOpaque(true);
        hint(control,"Choose a card background color. Opacity is controlled separately.");
        refreshers.add(()->{
            Color color=LootCardPainter.background(config.cardTheme(),config.cardBackgroundColor());
            control.setText(String.format(Locale.ROOT,"Choose: #%06X",color.getRGB()&0xffffff));control.setBackground(color);
            control.setForeground(color.getRed()*299+color.getGreen()*587+color.getBlue()*114>145000?Color.BLACK:Color.WHITE);
        });
        control.addActionListener(e->{
            Object profile=icons.configs.getProfile();Color before=config.cardBackgroundColor();ImprovedLootingConfig.CardTheme theme=config.cardTheme();
            Color chosen=JColorChooser.showDialog(this,"Card background color",LootCardPainter.background(theme,before));
            if(chosen!=null&&!closed&&Objects.equals(profile,icons.configs.getProfile())&&Objects.equals(before,config.cardBackgroundColor())&&theme==config.cardTheme())
                icons.configs.setConfiguration(ImprovedLootingConfig.GROUP,"cardBackgroundColor",new Color(chosen.getRGB()));
        });return control;
    }
    private JCheckBox toggle(JPanel parent,String label,String key,BooleanSupplier value)
    {
        JCheckBox control=new JCheckBox(label,value.getAsBoolean()); parent.add(control);
        refreshers.add(()->control.setSelected(value.getAsBoolean()));
        control.addActionListener(e->{ if(!syncing) icons.configs.setConfiguration(ImprovedLootingConfig.GROUP,key,control.isSelected()); });
        return control;
    }
    private JSpinner number(JPanel parent,String label,String key,IntSupplier value,int min,int max)
    {
        parent.add(new JLabel(label));JSpinner input=new JSpinner(new SpinnerNumberModel(Math.max(min,Math.min(max,value.getAsInt())),min,max,1));parent.add(input);
        input.addChangeListener(e->{if(!syncing) {int n=(Integer)input.getValue();if(key.equals("labelFontSize")&&n>0&&n<8)n=8;icons.configs.setConfiguration(ImprovedLootingConfig.GROUP,key,n);}});
        refreshers.add(()->input.setValue(Math.max(min,Math.min(max,value.getAsInt()))));return input;
    }
    private <T extends Enum<T>> JComboBox<T> choice(JPanel parent,String label,String key,T[] values,Supplier<T> value)
    {
        parent.add(new JLabel(label));JComboBox<T> input=new JComboBox<>(values);input.setSelectedItem(value.get());parent.add(input);
        input.addActionListener(e->{if(!syncing)icons.configs.setConfiguration(ImprovedLootingConfig.GROUP,key,input.getSelectedItem());});
        refreshers.add(()->input.setSelectedItem(value.get()));return input;
    }
    private static void section(JPanel parent,String title){JLabel label=new JLabel(title);label.setFont(label.getFont().deriveFont(Font.BOLD));label.setBorder(BorderFactory.createEmptyBorder(8,0,2,0));parent.add(label);}
    private static void enableControls(Container parent,boolean enabled){for(Component child:parent.getComponents()){child.setEnabled(enabled);if(child instanceof Container)enableControls((Container)child,enabled);}}
    private static JPanel column() { JPanel p=new JPanel(new net.runelite.client.ui.DynamicGridLayout(0,1,0,7)); p.setBorder(BorderFactory.createEmptyBorder(10,2,2,2)); return p; }
    private static JScrollPane scroll(JPanel panel) { JPanel outer=new JPanel(new BorderLayout());outer.add(panel,BorderLayout.NORTH);JScrollPane scroll=new JScrollPane(outer);scroll.setBorder(null);scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);return scroll; }
    private static String html(String text) { return "<html><body style='width:150px'>"+text+"</body></html>"; }
    private static JLabel help(String text) { return new JLabel(html(text)); }
    private static void hint(JComponent control,String text)
    {
        String tooltip=html(text);control.setToolTipText(tooltip);
        if(control instanceof JSpinner){JComponent editor=((JSpinner)control).getEditor();editor.setToolTipText(tooltip);if(editor instanceof JSpinner.DefaultEditor)((JSpinner.DefaultEditor)editor).getTextField().setToolTipText(tooltip);}
    }
    private JButton button(JPanel p,String text,Runnable action) { JButton b=new JButton(text); b.addActionListener(e->action.run()); p.add(b); return b; }
    void close() { closed=true; timer.stop(); if(browser!=null)browser.close();if(presets!=null)presets.close(); if(editor!=null) editor.close(); if(assets!=null) assets.close();if(tierEditor!=null)tierEditor.close(); }
}

package com.improvedlooting;

import com.google.inject.Provides;
import java.awt.*;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.*;
import net.runelite.client.events.*;
import net.runelite.client.plugins.*;
import net.runelite.client.ui.*;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(name="Improved Looting",internalName="improved-looting",description = "Style ground loot with cards, labels, GE or High Alchemy tiers, beams and custom sounds for valuable and special drops.",tags={"loot","filters","icons","ground"})
public class ImprovedLootingPlugin extends Plugin
{
    @Inject private ImprovedLootingConfig config;
    @Inject private ReleaseNotesNotice releaseNotes;
    @Inject private ItemIcons icons;
    @Inject private GroundLoot loot;
    @Inject private SpecialLootEvents specialEvents;
    @Inject private GroundLootOverlay overlay;
    @Inject private LootCardsOverlay cards;
    @Inject private LootPreferences preferences;
    @Inject private LootProfiles profiles;
    @Inject private LegacyImport migration;
    @Inject private MenuIconPublisher publisher;
    @Inject private EventBus events;
    @Inject private ClientThread thread;
    @Inject private ClientToolbar toolbar;
    @Inject private OverlayManager overlays;
    @Inject private LootLabelInput labelInput;
    @Inject private net.runelite.client.input.MouseManager mouseManager;
    private ImprovedLootingPanel panel;
    private NavigationButton navigation;
    private volatile boolean active;
    private volatile long lifecycle;
    @Provides ImprovedLootingConfig config(ConfigManager manager) { return manager.getConfig(ImprovedLootingConfig.class); }
    net.runelite.client.util.Filepath soundDirectory() throws java.io.IOException { return getPluginDirectory().joinSegment("tier-sounds"); }
    private void updateSidePanel()
    {
        SwingUtilities.invokeLater(() -> {
            if (!active || navigation == null) return;
            if (config.hideSidePanel()) toolbar.removeNavigation(navigation);
            else toolbar.addNavigation(navigation);
        });
    }

    @Override protected void startUp()
    {
        long token=++lifecycle;active=true;thread.invoke(()->{if(token==lifecycle){loot.clear();specialEvents.clear();overlay.clear();publisher.clear();}});
        icons.filters.reload(); icons.tiers.reload(); icons.tiers.specials.reload(); events.register(specialEvents); events.register(loot); events.register(publisher); overlays.add(overlay); overlays.add(cards);
        events.register(releaseNotes);releaseNotes.start();
        labelInput.start();mouseManager.registerMouseListener(labelInput);
        SwingUtilities.invokeLater(()->{
            if(!active || token!=lifecycle) return;
            closePanel();
            panel=new ImprovedLootingPanel(icons,config,loot,migration,thread,preferences,profiles);
            navigation=NavigationButton.builder().tooltip("Improved Looting").icon(icon()).priority(7).panel(panel).build(); if (!config.hideSidePanel()) toolbar.addNavigation(navigation);
        });
    }
    @Override protected void shutDown()
    {
        icons.tiers.stop(); icons.tiers.specials.stop(); events.unregister(specialEvents);
        releaseNotes.stop();events.unregister(releaseNotes);
        labelInput.stop();mouseManager.unregisterMouseListener(labelInput);
        long token=++lifecycle;active=false; events.unregister(loot); events.unregister(publisher); overlays.remove(overlay); overlays.remove(cards); thread.invoke(()->{if(token==lifecycle){loot.clear();specialEvents.clear();overlay.clear(); publisher.clear();}});
        SwingUtilities.invokeLater(()->{if(token==lifecycle)closePanel();});
    }
    @Subscribe public void onConfigChanged(ConfigChanged e)
    {
        if(!ImprovedLootingConfig.GROUP.equals(e.getGroup())) return;
        if(ReleaseNotesNotice.SEEN_KEY.equals(e.getKey())) return;
        if("hideSidePanel".equals(e.getKey())) { updateSidePanel(); return; }
        labelInput.reset();
        if(LootProfiles.SAVED.equals(e.getKey()) || LootProfiles.UNDO.equals(e.getKey()) || FilterIcons.BACKUP.equals(e.getKey()) || ItemIcons.BACKUP.equals(e.getKey())) return;
        if(FilterIcons.KEY.equals(e.getKey())) icons.filters.reload();
        if(PriceTiers.KEY.equals(e.getKey())) icons.tiers.reload();
        if(SpecialDropSounds.KEY.equals(e.getKey())) icons.tiers.specials.reload();
        long token=lifecycle;
        thread.invoke(()->{if(token==lifecycle && active){
            if(LootPreferences.KEY.equals(e.getKey()))loot.refreshOverrides();
            else {loot.refreshSettings();overlay.clear();}
            publisher.clear();
        }});
    }
    @Subscribe public void onProfileChanged(ProfileChanged e)
    {
        labelInput.reset();
        long token=++lifecycle;
        icons.filters.reload(); icons.tiers.reload(); icons.tiers.specials.reload(); thread.invoke(()->{if(token==lifecycle){loot.clear();specialEvents.clear();overlay.clear();publisher.clear();}});
        SwingUtilities.invokeLater(()->{if(token!=lifecycle)return;closePanel();if(active) rebuildPanel();});
    }
    @Subscribe public void onGameStateChanged(net.runelite.api.events.GameStateChanged e)
    {
        if(e.getGameState()!=net.runelite.api.GameState.LOGGED_IN){overlay.clear();labelInput.reset();}
    }
    private void closePanel(){if(panel!=null){panel.close();panel=null;}if(navigation!=null){toolbar.removeNavigation(navigation);navigation=null;}}
    private void rebuildPanel() { panel=new ImprovedLootingPanel(icons,config,loot,migration,thread,preferences,profiles); navigation=NavigationButton.builder().tooltip("Improved Looting").icon(icon()).priority(7).panel(panel).build(); if (!config.hideSidePanel()) toolbar.addNavigation(navigation); }
    static BufferedImage icon()
    {
        BufferedImage image=new BufferedImage(24,24,BufferedImage.TYPE_INT_ARGB); Graphics2D g=image.createGraphics();
        try {g.setColor(new Color(231,181,70));g.fillRoundRect(3,8,18,13,4,4);g.setColor(new Color(101,65,28));g.fillRect(3,12,18,2);g.setColor(Color.WHITE);g.fillRect(11,11,3,5);} finally {g.dispose();} return image;
    }
}

package com.improvedlooting;

import java.awt.*;
import java.io.*;
import java.util.*;
import java.util.List;
import javax.swing.*;
import net.runelite.client.util.Filepath;

final class ItemIconEditor
{
    private final ItemIcons icons;
    private final DefaultListModel<ItemIcons.Assignment> model=new DefaultListModel<>();
    private final JList<ItemIcons.Assignment> list=new JList<>(model);
    private JPanel panel;
    private final JLabel filterStatus=new JLabel();
    private JDialog dialog;
    private boolean closed;
    void close() { closed=true; if(dialog!=null) { dialog.dispose(); } }
    ItemIconEditor(ItemIcons icons) { this.icons=icons; }
    void open(Component owner)
    {
        closed=false;
        panel=new JPanel(new BorderLayout(8,8));
        panel.setBorder(BorderFactory.createEmptyBorder(10,10,10,10));
        JPanel heading=new JPanel(new GridLayout(0,1,0,5));
        heading.add(new JLabel("<html>Import the same Filterscape script used by Loot Filters; it is not linked automatically.<br>Use Appearance for ground labels. Improved Right-Clicks controls connected menu icons.</html>"));
        heading.add(filterStatus); panel.add(heading,BorderLayout.NORTH);
        heading.add(new JLabel("Manual icon overrides (shared with ground labels and connected menus)"));
        panel.add(new JScrollPane(list),BorderLayout.CENTER);
        JPanel buttons=new JPanel(new GridLayout(0,2,6,6));
        button(buttons,"Assign icon",this::assign);
        button(buttons,"Delete selected",() -> { List<ItemIcons.Assignment> next=icons.snapshot(); next.removeAll(list.getSelectedValuesList()); icons.save(next); refresh(); });
        button(buttons,"Import Loot Filters",this::importLoot);
        button(buttons,"Import/export icons",this::exchange);
        button(buttons,"Filter setup / backup",this::filterBackup);
        button(buttons,"Import filter sounds",this::importSounds);
        button(buttons,"Undo filter import",() -> { icons.filters.undo(); refresh(); JOptionPane.showMessageDialog(panel,icons.filters.status()); });
        button(buttons,"Undo / redo",() -> { icons.undo(); refresh(); });
        panel.add(buttons,BorderLayout.SOUTH);
        dialog=new JDialog(SwingUtilities.getWindowAncestor(owner),"Item icons",Dialog.ModalityType.MODELESS);
        dialog.addWindowListener(new java.awt.event.WindowAdapter() { @Override public void windowClosed(java.awt.event.WindowEvent e) { closed=true; } });
        dialog.setContentPane(panel); dialog.setSize(620,480); dialog.setMinimumSize(new Dimension(480,320));
        dialog.setLocationRelativeTo(owner); dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE); refresh(); dialog.setVisible(true);
    }
    private void refresh() { if(icons.filters!=null) filterStatus.setText(icons.filters.status()); model.clear(); for(ItemIcons.Assignment a:icons.snapshot()) { model.addElement(a); } }
    private void button(JPanel parent,String label,Runnable action)
    {
        JButton b=new JButton(label); b.addActionListener(e -> { try { action.run(); } catch(IllegalArgumentException ex) { JOptionPane.showMessageDialog(panel,ex.getMessage(),"Item icons",JOptionPane.WARNING_MESSAGE); } }); parent.add(b);
    }
    private Object profile() { return icons.configs.getProfile(); }
    private void checkProfile(Object original) { if(closed) throw new IllegalArgumentException("Icon editor was closed."); if(!Objects.equals(original,profile())) { refresh(); throw new IllegalArgumentException("RuneLite profile changed. Reopen this action."); } }
    private void assign()
    {
        Object original=profile();
        ItemPicker picker=new ItemPicker(icons.search);
        FilterIcons.Prepared filter=icons.filters.snapshot();
        IconPalette palette=new IconPalette(icons,filter==null?Collections.emptyMap():filter.bundle.images,false);
        picker.onSelect(palette::currentItem);
        JPanel form=new JPanel(new GridLayout(1,2,10,0)); form.add(picker); form.add(palette); form.setPreferredSize(new Dimension(680,300));
        ItemIcons.Assignment assignment=new ItemIcons.Assignment();
        try {
            if(JOptionPane.showConfirmDialog(panel,form,"Find item and choose icon",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION) return;
            checkProfile(original);
            IconPalette.Selection selected=palette.selection();
            assignment.name=picker.value().trim(); assignment.kind=selected.kind;
            assignment.iconId=selected.item; assignment.image=selected.image;
            if(assignment.name.contains("*")) throw new IllegalArgumentException("Manual overrides use exact item names. Use Edit filter rules for wildcards.");
            List<ItemIcons.Assignment> next=icons.snapshot(); next.removeIf(old -> old.key().equals(assignment.key())); next.add(assignment); icons.save(next); refresh();
        } finally { picker.close(); palette.close(); }
    }
    private <T> void background(java.util.concurrent.Callable<T> work,java.util.function.Consumer<T> done)
    {
        new SwingWorker<T,Void>() {
            protected T doInBackground() throws Exception { return work.call(); }
            protected void done() {
                if(closed) return;
                try { done.accept(get()); }
                catch(Exception e) { Throwable cause=e.getCause()==null ? e : e.getCause(); JOptionPane.showMessageDialog(panel,cause.getMessage(),"Import not applied",JOptionPane.WARNING_MESSAGE); }
            }
        }.execute();
    }
    private static String readFilter(Filepath file) throws IOException
    {
        try(java.io.InputStream in=file.openInputStream()) {
            byte[] data=in.readNBytes(1000001); if(data.length>1000000) throw new IllegalArgumentException("Filter exceeds 1 MB.");
            return new String(data,java.nio.charset.StandardCharsets.UTF_8);
        }
    }
    void importLoot()
    {
        Object original=profile();
        Object[] choices={"Choose .rs2f file","Paste Filterscape text","Cancel"};
        int choice=JOptionPane.showOptionDialog(panel,"Import icon rules from a Filterscape export or Loot Filters script.\nThe original files and settings remain untouched.","Import Loot Filters",JOptionPane.DEFAULT_OPTION,JOptionPane.PLAIN_MESSAGE,null,choices,choices[0]);
        if(choice==0) {
            List<Filepath> files=new Filepath.Chooser().setIsOpen().setAcceptsFiles().addExtensionFilter("Loot Filters","rs2f","txt").showDialog(panel);
            if(files.isEmpty()) return;
            background(() -> readFilter(files.get(0)),source -> compileImport(source,original));
        } else if(choice==1) {
            JTextArea text=new JTextArea(18,48);
            if(JOptionPane.showConfirmDialog(panel,new JScrollPane(text),"Paste generated filter",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION) compileImport(text.getText(),original);
        }
    }
    private void compileImport(String source,Object original)
    {
        checkProfile(original);
        background(() -> com.improvedlooting.rs2f.LootFilter.compile(source),program -> {
            checkProfile(original);
            FilterIcons.Bundle bundle=new FilterIcons.Bundle(); bundle.compressedSource=FilterIcons.compress(source);
            Set<String> files=program.files();
            if(files.size()>128) throw new IllegalArgumentException("Use at most 128 custom images.");
            for(String file:files) IconImages.safeName(file);
            if(files.isEmpty()) { background(() -> icons.filters.prepare(bundle),ready -> previewFilter(ready,original)); return; }
            JOptionPane.showMessageDialog(panel,"This filter references "+files.size()+" images. Select the Loot Filters icons folder (usually .runelite/loot-filters/icons).\nImages will be embedded in our backup; originals stay untouched.\nAll referenced images must be present before import can apply.");
            List<Filepath> folders=new Filepath.Chooser().setIsOpen().setAcceptsDirectories().showDialog(panel);
            if(folders.isEmpty()) return;
            background(() -> {
                for(String file:files) {
                    Filepath path=folders.get(0);
                    for(String segment:IconImages.safeName(file).split("/")) path=path.joinSegment(segment);
                    bundle.images.put(file,IconImages.read(path));
                }
                return icons.filters.prepare(bundle);
            },ready -> previewFilter(ready,original));
        });
    }
    private void previewFilter(FilterIcons.Prepared ready,Object original)
    {
        checkProfile(original);
        String message=ready.program.rules.size()+" rules and "+ready.images.size()+" images ready.\n\nConditions, macros, rule order and inherited icons are preserved.\nLabels, colors, hiding, sounds and loot beams follow the same rules. Master controls remain in the side panel.\nManual item assignments take priority. This replaces the previously imported filter; Undo filter import restores it.";
        if(JOptionPane.showConfirmDialog(panel,message,"Review filter import",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION) return;
        checkProfile(original); icons.filters.save(ready); refresh(); JOptionPane.showMessageDialog(panel,"Imported. Ground display follows the Appearance tab.");
    }
    private void filterBackup()
    {
        Object original=profile();
        Object[] options={"Copy / paste backup","Disable imported filter","Cancel"};
        int action=JOptionPane.showOptionDialog(panel,icons.filters.status(),"Imported filter",JOptionPane.DEFAULT_OPTION,JOptionPane.PLAIN_MESSAGE,null,options,options[0]);
        if(action==1) { checkProfile(original); icons.filters.save(null); refresh(); return; }
        if(action!=0) return;
        JTextArea text=new JTextArea(icons.filters.export(),18,48); text.setLineWrap(true);
        if(JOptionPane.showConfirmDialog(panel,new JScrollPane(text),"Copy to export; paste a filter setup to import",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION) return;
        String raw=text.getText(); background(() -> icons.filters.parse(raw),ready -> previewFilter(ready,original));
    }
    private void importSounds()
    {
        Object original=profile(); String before=icons.filters.export();
        if(before.isBlank()) throw new IllegalArgumentException("Import or save a filter first.");
        FilterIcons.Bundle bundle=icons.gson.fromJson(before,FilterIcons.Bundle.class);
        Set<String> names=new LinkedHashSet<>();
        for(com.improvedlooting.rs2f.FilterRule rule:com.improvedlooting.rs2f.LootFilter.compile(FilterIcons.source(bundle)).rules) {
            com.improvedlooting.rs2f.model.SoundProvider sound=rule.getDisplay().getSound();
            if(sound!=null && sound.getFile()!=null) { IconImages.safeName(sound.getFile()); names.add(sound.getFile()); }
        }
        if(names.isEmpty()) { JOptionPane.showMessageDialog(panel,"This filter has no custom sound files."); return; }
        JOptionPane.showMessageDialog(panel,"Select the folder containing the filter's sound files. Copies are saved with your filter; the originals are unchanged.");
        List<Filepath> folders=new Filepath.Chooser().setIsOpen().setAcceptsDirectories().showDialog(panel);
        if(folders.isEmpty()) return;
        background(() -> {
            if(bundle.sounds==null) bundle.sounds=new LinkedHashMap<>();
            for(String name:names) {
                Filepath file=folders.get(0);
                for(String part:IconImages.safeName(name).split("/")) file=file.joinSegment(part);
                bundle.sounds.put(name,FilterSounds.read(file));
            }
            return icons.filters.prepare(bundle);
        },ready -> {
            checkProfile(original);
            if(!Objects.equals(before,icons.filters.export())) throw new IllegalArgumentException("The active filter changed. Import sounds again.");
            icons.filters.save(ready); refresh(); JOptionPane.showMessageDialog(panel,"Imported "+ready.sounds.size()+" sound files. Enable Drop sounds to use them.");
        });
    }
    private void preview(List<ItemIcons.Assignment> imported,Object original)
    {
        JTextArea text=new JTextArea(14,42); text.setEditable(false);
        text.append("ICON ASSIGNMENTS ONLY. Filter colors, sounds and hiding rules are not imported.\n\n");
        for(ItemIcons.Assignment a:imported) { text.append(a.toString()+"\n"); }
        Object[] actions={"Merge (keep existing)","Replace all","Cancel"};
        int choice=JOptionPane.showOptionDialog(panel,new JScrollPane(text),"Review icon import",JOptionPane.DEFAULT_OPTION,JOptionPane.PLAIN_MESSAGE,null,actions,actions[0]);
        if(choice!=0 && choice!=1) { return; }
        checkProfile(original);
        LinkedHashMap<String,ItemIcons.Assignment> next=new LinkedHashMap<>();
        if(choice==0) { for(ItemIcons.Assignment a:icons.snapshot()) { next.put(a.key(),a); } }
        for(ItemIcons.Assignment a:imported) { next.putIfAbsent(a.key(),a); }
        icons.save(new ArrayList<>(next.values())); refresh();
    }
    private void exchange()
    {
        Object original=profile(); JTextArea json=new JTextArea(icons.export(),16,42); json.setLineWrap(true);
        if(JOptionPane.showConfirmDialog(panel,new JScrollPane(json),"Copy to export; paste to import",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION) { return; }
        checkProfile(original); preview(icons.parse(json.getText()),original);
    }
}

package com.improvedlooting;

import com.google.gson.Gson;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;

@Singleton
class ItemIcons
{
    static final String KEY="itemIconAssignments", BACKUP="itemIconBackup";
    enum Kind { HEART, STAR, DIAMOND, CURRENT_ITEM, ITEM, SPRITE, IMAGE }
    static final class Assignment
    {
        String image; String name; int itemId=-1; Kind kind; int iconId; int spriteIndex;
        String key() { return itemId>=0 ? "id:"+itemId : "name:"+name.toLowerCase(Locale.ROOT); }
        @Override public String toString() { return (itemId>=0 ? "Item #"+itemId : name)+" — "+kind+(kind==Kind.ITEM || kind==Kind.SPRITE ? " #"+iconId : ""); }
    }
    @Inject ConfigManager configs;
    @Inject Gson gson;
    @Inject ItemManager items;
    @Inject SpriteManager sprites;
    @Inject FilterIcons filters;
    @Inject ItemSearch search;
    @Inject PriceTiers tiers;
    @Inject net.runelite.client.audio.AudioPlayer audio;
    private final Map<String,BufferedImage> imageCache=new LinkedHashMap<>();
    private final Map<Kind,BufferedImage> builtins=new EnumMap<>(Kind.class);
    private long cachedPixels;
    private String cached;
    private List<Assignment> assignments=Collections.emptyList();
    synchronized List<Assignment> snapshot()
    {
        String raw=configs.getConfiguration(ImprovedLootingConfig.GROUP,KEY);
        if(!Objects.equals(raw,cached))
        {
            try { assignments=parse(raw==null ? "[]" : raw); }
            catch(IllegalArgumentException e) { assignments=Collections.emptyList(); }
            cached=raw; imageCache.clear();cachedPixels=0;
        }
        return new ArrayList<>(assignments);
    }
    List<Assignment> parse(String raw)
    {
        if(raw==null || raw.length()>6000000) { throw new IllegalArgumentException("Icon data is too large."); }
        try
        {
            Assignment[] data=gson.fromJson(raw,Assignment[].class);
            if(data==null || data.length>500) { throw new IllegalArgumentException("Use at most 500 assignments."); }
            LinkedHashMap<String,Assignment> unique=new LinkedHashMap<>();
            long pixels=0;
            for(Assignment a:data)
            {
                if(a==null || a.kind==null || a.itemId < -1 || a.itemId>100000 || a.iconId<0 || a.iconId>100000 || a.spriteIndex<0 || a.spriteIndex>255
                    || (a.itemId<0 && (a.name==null || a.name.trim().isEmpty() || a.name.length()>120 || a.name.contains("<") || a.name.contains(">"))))
                { throw new IllegalArgumentException("Invalid icon assignment."); }
                if(a.kind==Kind.IMAGE) { BufferedImage image=IconImages.decode(a.image);pixels+=(long)image.getWidth()*image.getHeight();if(pixels>16000000)throw new IllegalArgumentException("Assignment images exceed 16 million pixels"); }
                if(a.name!=null) { a.name=a.name.trim(); }
                unique.put(a.key(),a);
            }
            return new ArrayList<>(unique.values());
        }
        catch(com.google.gson.JsonParseException e) { throw new IllegalArgumentException("Invalid icon JSON."); }
    }
    String export() { return gson.toJson(snapshot()); }
    void save(List<Assignment> next)
    {
        String json=gson.toJson(next); parse(json);
        configs.setConfiguration(ImprovedLootingConfig.GROUP,BACKUP,export());
        configs.setConfiguration(ImprovedLootingConfig.GROUP,KEY,json);
    }
    void undo()
    {
        String before=configs.getConfiguration(ImprovedLootingConfig.GROUP,BACKUP);
        if(before!=null) { save(parse(before)); }
    }
    Assignment find(int id)
    {
        List<Assignment> entries=snapshot();
        for(Assignment a:entries) { if(a.itemId==id) { return a; } }
        if(entries.isEmpty()) { return null; }
        String name=items.getItemComposition(id).getName();
        for(Assignment a:entries) { if(a.itemId<0 && a.name.equalsIgnoreCase(name)) { return a; } }
        return null;
    }
    synchronized BufferedImage image(Assignment a,int id)
    {
        if(a==null) { return null; }
        if(a.kind==Kind.CURRENT_ITEM || a.kind==Kind.ITEM) { return items.getImage(a.kind==Kind.CURRENT_ITEM ? id : a.iconId); }
        if(a.kind==Kind.IMAGE) {
            BufferedImage cached=imageCache.get(a.image);if(cached!=null)return cached;
            BufferedImage next=IconImages.decode(a.image);long pixels=(long)next.getWidth()*next.getHeight();
            if(imageCache.size()>=128 || cachedPixels+pixels>16000000){imageCache.clear();cachedPixels=0;}
            imageCache.put(a.image,next);cachedPixels+=pixels;return next;
        }
        if(a.kind==Kind.SPRITE) { try { return sprites.getSprite(a.iconId,a.spriteIndex); } catch(IndexOutOfBoundsException e) { return null; } }
        if(builtins.containsKey(a.kind)) { return builtins.get(a.kind); }
        BufferedImage result=new BufferedImage(17,15,BufferedImage.TYPE_INT_ARGB);
        Graphics2D g=result.createGraphics();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);
            if(a.kind==Kind.HEART) { g.setColor(new Color(255,105,110)); g.fillOval(1,1,8,8); g.fillOval(8,1,8,8); g.fillPolygon(new int[]{1,16,8},new int[]{6,6,14},3); }
            else if(a.kind==Kind.DIAMOND) { g.setColor(Color.CYAN); g.fillPolygon(new int[]{8,15,8,1},new int[]{0,7,14,7},4); }
            else { g.setColor(new Color(255,210,60)); Polygon star=new Polygon(); for(int i=0;i<10;i++) { double angle=-Math.PI/2+i*Math.PI/5; double radius=i%2==0 ? 7 : 3; star.addPoint(8+(int)(Math.cos(angle)*radius),7+(int)(Math.sin(angle)*radius)); } g.fillPolygon(star); }
        }
        finally { g.dispose(); }
        builtins.put(a.kind,result);
        return result;
    }
}

package com.improvedlooting;

import java.awt.*;
import java.awt.event.*;
import java.util.function.Consumer;
import javax.swing.*;
import javax.swing.event.*;

final class ItemPicker extends JPanel
{
    private final JTextField query=new JTextField();
    private final DefaultListModel<ItemSearch.Choice> model=new DefaultListModel<>();
    private final JList<ItemSearch.Choice> results=new JList<>(model);
    private final JLabel hint=new JLabel("Type at least 2 letters to search items");
    private final javax.swing.Timer debounce;
    private volatile int revision;
    private volatile boolean closed;
    private boolean choosing;
    private ItemSearch.Choice selected;
    private Consumer<ItemSearch.Choice> onSelect=c -> {};
    ItemPicker(ItemSearch search) { this(search,4); }
    ItemPicker(ItemSearch search,int rows)
    {
        super(new BorderLayout(4,4)); add(query,BorderLayout.NORTH);
        results.setVisibleRowCount(rows); results.setFixedCellHeight(34); results.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        results.setCellRenderer(new DefaultListCellRenderer() {
            @Override public Component getListCellRendererComponent(JList<?> list,Object value,int index,boolean selected,boolean focus) {
                JLabel label=(JLabel)super.getListCellRendererComponent(list,value,index,selected,focus);
                ItemSearch.Choice choice=(ItemSearch.Choice)value; label.setText(choice.name); label.setIcon(choice.image==null?null:new ImageIcon(choice.image));
                label.setBorder(BorderFactory.createEmptyBorder(2,6,2,6)); return label;
            }
        });
        JScrollPane scroll=new JScrollPane(results); scroll.setPreferredSize(new Dimension(240,rows*34+4)); add(scroll,BorderLayout.CENTER); add(hint,BorderLayout.SOUTH);
        debounce=new javax.swing.Timer(180,e -> {
            int current=revision; String term=query.getText();
            if(term.trim().length()<2) { hint.setText("Type at least 2 letters to search items"); return; }
            hint.setText("Searching item catalogue…");
            search.search(term,() -> !closed && revision==current,choices -> {
                if(closed || revision!=current) return;
                model.clear(); for(ItemSearch.Choice choice:choices) {
                    model.addElement(choice);
                    if(choice.image instanceof net.runelite.client.util.AsyncBufferedImage)
                        ((net.runelite.client.util.AsyncBufferedImage)choice.image).onLoaded(() -> SwingUtilities.invokeLater(() -> { if(!closed) results.repaint(); }));
                }
                hint.setText(choices.isEmpty()?"No matches. Exact names / * still work.":"Click a match, or use ↓ and Enter.");
                results.repaint();
            });
        }); debounce.setRepeats(false);
        query.getDocument().addDocumentListener(new DocumentListener() {
            public void insertUpdate(DocumentEvent e) { changed(); }
            public void removeUpdate(DocumentEvent e) { changed(); }
            public void changedUpdate(DocumentEvent e) { changed(); }
            private void changed() { if(choosing) return; selected=null; revision++; model.clear(); debounce.restart(); onSelect.accept(null); }
        });
        query.addKeyListener(new KeyAdapter() { @Override public void keyPressed(KeyEvent e) { if(e.getKeyCode()==KeyEvent.VK_DOWN && !model.isEmpty()) { results.setSelectedIndex(0); results.requestFocusInWindow(); e.consume(); } } });
        results.addMouseListener(new MouseAdapter() { @Override public void mouseClicked(MouseEvent e) { int i=results.locationToIndex(e.getPoint()); if(i>=0 && results.getCellBounds(i,i).contains(e.getPoint())) choose(); } });
        results.getInputMap().put(KeyStroke.getKeyStroke("ENTER"),"choose");
        results.getActionMap().put("choose",new AbstractAction() { public void actionPerformed(ActionEvent e) { choose(); } });
    }
    void onSelect(Consumer<ItemSearch.Choice> action) { onSelect=action; }
    private void choose()
    {
        ItemSearch.Choice choice=results.getSelectedValue(); if(choice==null) return;
        choosing=true; query.setText(choice.name); choosing=false; selected=choice; revision++; debounce.stop();
        hint.setText("Selected: "+choice.name); onSelect.accept(choice); query.requestFocusInWindow();
    }
    void value(String name) { query.setText(name); }
    String value() { return query.getText(); }
    ItemSearch.Choice selected() { return selected; }
    void close() { closed=true; revision++; debounce.stop(); }
}

package com.improvedlooting;

import java.awt.image.BufferedImage;
import java.util.*;
import java.util.function.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;

@Singleton
final class ItemSearch
{
    static final class Choice
    {
        final int id;
        final String name, lower;
        BufferedImage image;
        Choice(int id, String name) { this.id=id; this.name=name; this.lower=name.toLowerCase(Locale.ROOT); }
        @Override public String toString() { return name; }
    }
    @Inject Client client;
    @Inject ClientThread thread;
    @Inject ItemManager items;
    private final Map<String, Choice> catalogue=new LinkedHashMap<>();
    private int cursor, size;

    void search(String query, BooleanSupplier wanted, Consumer<java.util.List<Choice>> done)
    {
        thread.invokeLater(() -> {
            if(!wanted.getAsBoolean()) return true;
            int count=Math.min(client.getItemCount(),100000);
            if(count<=0) { SwingUtilities.invokeLater(() -> done.accept(Collections.emptyList())); return true; }
            if(count!=size) { catalogue.clear(); cursor=0; size=count; }
            int end=Math.min(cursor+512,size);
            while(cursor<end) {
                int id=cursor++; ItemComposition item=items.getItemComposition(id);
                String name=item.getName();
                if(name!=null && !name.isBlank() && !name.equalsIgnoreCase("null") && item.getNote()==-1 && item.getPlaceholderTemplateId()==-1)
                    catalogue.putIfAbsent(name.toLowerCase(Locale.ROOT),new Choice(id,name));
            }
            if(cursor<size) return false;
            java.util.List<Choice> result=rank(catalogue.values(),query);
            for(Choice choice:result) choice.image=items.getImage(choice.id);
            SwingUtilities.invokeLater(() -> { if(wanted.getAsBoolean()) done.accept(result); });
            return true;
        });
    }
    static java.util.List<Choice> rank(Collection<Choice> choices,String query)
    {
        String q=query.trim().toLowerCase(Locale.ROOT);
        if(q.length()<2) return Collections.emptyList();
        java.util.List<Choice> result=new ArrayList<>();
        for(Choice choice:choices) if(choice.lower.contains(q)) result.add(choice);
        result.sort(Comparator.comparingInt((Choice c) -> c.lower.equals(q)?0:c.lower.startsWith(q)?1:2).thenComparing(c -> c.lower));
        return new ArrayList<>(result.subList(0,Math.min(40,result.size())));
    }
}

package com.improvedlooting;

import java.util.*;
import javax.inject.*;
import net.runelite.client.config.ConfigManager;

@Singleton
final class LegacyImport
{
    @Inject ConfigManager configs;
    @Inject FilterIcons filters;
    @Inject ItemIcons icons;
    static final String SOURCE="improvedmenus";
    Map<String,String> prepare()
    {
        Map<String,String> copy=new LinkedHashMap<>();
        String filter=configs.getConfiguration(SOURCE,FilterIcons.KEY);
        String assignments=configs.getConfiguration(SOURCE,ItemIcons.KEY);
        if(filter!=null && !filter.isBlank()) { filters.parse(filter); copy.put(FilterIcons.KEY,filter); }
        if(assignments!=null && !assignments.isBlank()) { icons.parse(assignments); copy.put(ItemIcons.KEY,assignments); }
        return copy;
    }
    void apply(Map<String,String> copy)
    {

        for(String key:copy.keySet()) {
            String existing=configs.getConfiguration(ImprovedLootingConfig.GROUP,key);
            if(existing!=null && !existing.isBlank()) throw new IllegalArgumentException("A setup already exists here. Export it and clear it before copying another setup.");
        }
        copy.forEach((key,value)->configs.setConfiguration(ImprovedLootingConfig.GROUP,key,value));
        filters.reload();
    }
}

package com.improvedlooting;

import com.improvedlooting.rs2f.model.SoundProvider;
import java.io.ByteArrayInputStream;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.Notifier;
import net.runelite.client.audio.AudioPlayer;

@Singleton
final class LootAlerts
{
    @Inject Client client;
    @Inject ImprovedLootingConfig config;
    @Inject Notifier notifier;
    @Inject AudioPlayer audio;
    @Inject ScheduledExecutorService executor;
    @Inject PriceTiers tiers;
    @Inject SpecialDropSounds specials;
    private final AtomicBoolean playing = new AtomicBoolean();
    private final Map<String, Integer> recent = new LinkedHashMap<>();
    private final Deque<Card> cards = new ArrayDeque<>();
    private final List<Pending> pending = new ArrayList<>();
    private final Map<String, Integer> logEntries = new LinkedHashMap<>();
    private int lastPet = Integer.MIN_VALUE / 2;
    private int lastSound = Integer.MIN_VALUE / 2;
    private int notificationTick=-1, notifications;
    private volatile int generation;
    static final class Card
    {
        final String text; final int expires;
        Card(String text, int expires) { this.text = text; this.expires = expires; }
    }
    static final class Sound
    {
        final byte[] bytes; final Integer effect; final int volume;
        Sound(byte[] bytes, Integer effect, int volume) { this.bytes = bytes; this.effect = effect; this.volume = volume; }
    }
    static final class Pending
    {
        String name;
        final int tick;
        boolean pet, collection, untradeable, dropSettled, pricePending;
        long value;
        Long profile;
        Sound rule, price;
        Pending(String name, int tick) { this.name = name; this.tick = tick; }
    }
    void clear() { generation++; recent.clear(); cards.clear(); pending.clear(); logEntries.clear(); lastPet = Integer.MIN_VALUE / 2; lastSound = Integer.MIN_VALUE / 2; }
    void tick()
    {
        int tick = client.getTickCount();
        recent.values().removeIf(expiry -> expiry < tick);
        cards.removeIf(card -> card.expires < tick);
        logEntries.values().removeIf(expiry -> expiry < tick);
    }
    List<Card> cards() { return new ArrayList<>(cards); }
    void drop(GroundLoot.Entry entry, FilterIcons.Prepared filter)
    {
        if (entry.display == null || entry.display.isHidden() || LootDisplayOptions.ownershipHidden(config,entry)) return;
        int tick = client.getTickCount();
        String key = entry.item.getId() + ":" + entry.tile.getLocalLocation() + ":" + entry.facts.getQuantity();
        if (recent.containsKey(key)) return;
        if (recent.size() >= 256) recent.remove(recent.keySet().iterator().next());
        recent.put(key, tick + 3);
        String message = "Loot: " + entry.facts.getName() + " × " + entry.facts.getQuantity();
        if (entry.display.isNotify())
        {
            if (config.lootNotifications()) notifyBounded(message);
            card(message);
        }
        SoundProvider sound = entry.display.getSound();
        Sound rule = sound == null ? null : new Sound(sound.getFile() == null ? null : filter.sounds.get(sound.getFile()), sound.getEffect(), 100);
        Sound selected = rule;
        PriceTiers.Ready ready = config.priceTiersEnabled() ? tiers.snapshot() : null;
        if (ready != null)
        {
            int index = PriceTiers.index(ready.setup, LootValues.value(config,entry.facts,entry.facts.getQuantity()));
            PriceTiers.Sound mode = ready.setup.tiers[index].sound;
            if (mode != PriceTiers.Sound.RULE) selected = new Sound(mode == PriceTiers.Sound.CUSTOM ? ready.audio[index] : null, null, 100);
        }
        Pending next = matching(entry.facts.getName());
        if (next == null) { next = new Pending(entry.facts.getName(), tick); add(next); }
        next.dropSettled |= tick > entry.spawnTick;
        next.untradeable = !entry.facts.isTradeable(); next.rule = rule; next.price = selected;
        next.value = LootValues.value(config, entry.facts, entry.facts.getQuantity());
        next.pricePending = config.priceTiersEnabled() && ready == null;
    }
    private Pending matching(String name)
    {
        String key = SpecialDropSounds.itemKey(name);
        for (Pending item : pending) if (SpecialDropSounds.itemKey(item.name).equals(key)) return item;
        return null;
    }
    private void add(Pending next)
    {
        next.profile = profile();
        if (pending.size() >= 256)
        {
            Pending ordinary = pending.stream().filter(p -> !p.pet && !p.collection).findFirst().orElse(null);
            if (ordinary == null) return;
            pending.remove(ordinary);
        }
        pending.add(next);
    }
    void special(String name, boolean pet, boolean collection)
    {
        int tick = client.getTickCount();
        String key = SpecialDropSounds.itemKey(name);
        if (collection)
        {
            if (logEntries.containsKey(key)) return;
            if (logEntries.size() >= 256) logEntries.remove(logEntries.keySet().iterator().next());
            logEntries.put(key, tick + 100);
        }
        Pending next = matching(name);
        if (pet)
        {
            Pending priorPet = pending.stream().filter(p -> p.pet && tick - p.tick <= 5).findFirst().orElse(null);
            if (priorPet != null)
            {
                if (next != null && next != priorPet) { priorPet.rule = next.rule; priorPet.price = next.price; priorPet.pricePending = next.pricePending; priorPet.value = next.value; priorPet.dropSettled |= next.dropSettled; pending.remove(next); }
                next = priorPet;
                if (!name.isEmpty()) next.name = name;
            }
            else if (tick - lastPet <= 5) return;
            lastPet = tick;
        }
        if (next == null) { next = new Pending(name, tick); add(next); }
        next.pet |= pet; next.collection |= collection;
    }
    Sound resolve(Pending item)
    {
        SpecialDropSounds.Ready special = specials == null ? null : specials.snapshot();
        SpecialDropSounds.Choice choice = special == null ? null : SpecialDropSounds.match(special.setup, item.name, item.pet, item.collection, item.untradeable);
        if (choice == null) return item.price;
        if (choice.mode == SpecialDropSounds.Mode.CUSTOM) return new Sound(special.audio.get(choice.audio), null, choice.volume);
        if (choice.mode == SpecialDropSounds.Mode.TIER)
        {
            PriceTiers.Ready price = tiers == null ? null : tiers.snapshot();
            if (price != null)
            {
                int index = choice.tier - 1;
                if (price.setup.tiers[index].sound == PriceTiers.Sound.CUSTOM) return new Sound(price.audio[index], null, choice.volume);
                if (price.setup.tiers[index].sound == PriceTiers.Sound.RULE && item.rule != null) return new Sound(item.rule.bytes, item.rule.effect, choice.volume);
            }
        }
        return new Sound(null, null, choice.volume);
    }
    void flush()
    {
        int tick = client.getTickCount();
        if (!config.lootSounds()) { pending.clear(); return; }
        Long profile = profile();
        pending.removeIf(p -> !Objects.equals(p.profile, profile) || tick - p.tick > (p.pet || p.collection ? 100 : 5));
        if (specials != null && specials.snapshot() == null) return;
        pending.sort(Comparator.comparingInt(this::priority));
        for (Iterator<Pending> it = pending.iterator(); it.hasNext();)
        {
            Pending next = it.next();
            if (!prepareSound(next))
            {
                if (next.pet || next.collection) break;
                continue;
            }
            Sound sound = resolve(next);
            boolean audible = sound != null && (sound.bytes != null || sound.effect != null) && sound.volume > 0 && config.alertVolume() > 0;
            if (!next.dropSettled && tick <= next.tick)
            {
                if ((next.pet || next.collection) && audible) break;
                continue;
            }
            if (!audible) { it.remove(); continue; }
            boolean urgent = next.pet || next.collection;
            if (!urgent && tick - lastSound < Math.ceil(clamp(config.soundCooldown(), 0, 60) / 0.6)) { it.remove(); continue; }
            if (playing.get()) { if (!urgent) it.remove(); continue; }
            play(sound, tick); it.remove();
        }
    }
    private boolean prepareSound(Pending item)
    {
        SpecialDropSounds.Ready special = specials == null ? null : specials.snapshot();
        SpecialDropSounds.Choice choice = special == null ? null
            : SpecialDropSounds.match(special.setup, item.name, item.pet, item.collection, item.untradeable);
        PriceTiers.Ready ready = tiers == null ? null : tiers.snapshot();
        if (choice != null) return choice.mode != SpecialDropSounds.Mode.TIER || ready != null;
        if (!item.pricePending) return true;
        if (!config.priceTiersEnabled())
        {
            item.price = item.rule;
        }
        else
        {
            if (ready == null) return false;
            int index = PriceTiers.index(ready.setup, item.value);
            PriceTiers.Sound mode = ready.setup.tiers[index].sound;
            item.price = mode == PriceTiers.Sound.RULE ? item.rule
                : new Sound(mode == PriceTiers.Sound.CUSTOM ? ready.audio[index] : null, null, 100);
        }
        item.pricePending = false;
        return true;
    }
    private int priority(Pending item)
    {
        if (item.pet) return 0;
        if (item.collection) return 1;
        SpecialDropSounds.Ready special = specials == null ? null : specials.snapshot();
        if (special != null)
        {
            for (Map.Entry<String, SpecialDropSounds.Choice> entry : special.setup.items.entrySet())
                if (entry.getValue().mode != SpecialDropSounds.Mode.INHERIT
                    && SpecialDropSounds.itemKey(entry.getKey()).equals(SpecialDropSounds.itemKey(item.name))) return 2;
            SpecialDropSounds.Kind clue = SpecialDropSounds.clue(item.name);
            if (clue != null && special.setup.categories.get(clue).mode != SpecialDropSounds.Mode.INHERIT) return 3;
            if (item.untradeable && special.setup.categories.get(SpecialDropSounds.Kind.UNTRADEABLE).mode != SpecialDropSounds.Mode.INHERIT) return 4;
        }
        return 5;
    }
    private void play(Sound sound, int tick)
    {
        int volume = clamp(config.alertVolume(), 0, 100) * sound.volume / 100;
        if (sound.bytes != null)
        {
            if (!playing.compareAndSet(false, true)) return;
            byte[] bytes = sound.bytes; int token = generation; float gain = gain(volume);
            Long profile = profile();
            lastSound = tick;
            executor.execute(() -> {
                try { if (token == generation && Objects.equals(profile, profile()) && config.lootSounds()) audio.play(new ByteArrayInputStream(bytes), gain); }
                catch (Exception ignored) { }
                finally { playing.set(false); }
            });
        }
        else if (sound.effect != null)
        {
            client.playSoundEffect(sound.effect, volume * 127 / 100);
            lastSound = tick;
        }
    }
    private Long profile() { return tiers == null ? null : ProfileIdentity.current(tiers.configs); }
    void despawn(GroundLoot.Entry entry, int seconds)
    {
        if (LootDisplayOptions.ownershipHidden(config,entry)) return;
        int threshold = clamp(config.despawnSeconds(), 1, 120);
        if (seconds > threshold) entry.warningArmed = true;
        if (!entry.warningArmed || entry.warned || seconds < 0 || seconds > threshold) return;
        entry.warned = true;
        if (!config.despawnWarnings() || entry.display.isHidden()
            || LootValues.value(config,entry.facts,entry.facts.getQuantity()) < Math.max(0, config.despawnMinimum())) return;
        String message = entry.facts.getName() + " despawns in " + seconds + "s";
        notifyBounded(message); card(message);
    }
    private void notifyBounded(String message)
    {
        int tick=client.getTickCount();if(notificationTick!=tick){notificationTick=tick;notifications=0;}
        if(notifications++<3)notifier.notify(message);
    }
    private void card(String message)
    {
        if (!config.notificationCards()) return;
        while (cards.size() >= 5) cards.removeFirst();
        cards.addLast(new Card(message, client.getTickCount() + 13));
    }
    static float gain(int percent) { return percent <= 0 ? -80f : (float)(20 * Math.log10(clamp(percent, 1, 100) / 100.0)); }
    static int clamp(int value, int min, int max) { return Math.max(min, Math.min(max, value)); }
}

