package com.improvedlooting;

import java.awt.Color;
import net.runelite.api.TileItem;

final class LootDisplayOptions
{
    static boolean detail(ImprovedLootingConfig.DetailMode mode,boolean rule)
    { return mode==ImprovedLootingConfig.DetailMode.ALWAYS || mode==ImprovedLootingConfig.DetailMode.RULES && rule; }
    static long price(ImprovedLootingConfig config,GroundLoot.Entry entry)
    { return !config.lootCompact() && detail(config.priceDisplay(),entry.display.isShowValue()) ? LootValues.value(config,entry.facts,entry.renderQuantity):0; }
    static int seconds(ImprovedLootingConfig config,GroundLoot.Entry entry,int tick)
    { return !config.lootCompact() && detail(config.timerDisplay(),entry.display.isShowDespawn()) && entry.renderDespawn>0 && entry.renderDespawn<Integer.MAX_VALUE ? LootResolution.secondsRemaining(entry.renderDespawn,tick):-1; }
    static boolean hidden(boolean ruleHidden,Boolean manual,long price,int minimum)
    { return manual!=null?manual:ruleHidden || price<Math.max(0,minimum); }
    static boolean untradeable(GroundLoot.Entry entry)
    { return entry.facts != null && !entry.facts.isTradeable(); }
    static int minimum(ImprovedLootingConfig config,GroundLoot.Entry entry)
    { return config.keepUntradeablesVisible() && untradeable(entry) ? 0 : config.minimumLabelValue(); }
    static boolean ownershipHidden(ImprovedLootingConfig config,GroundLoot.Entry entry)
    {
        int ownership=entry.item.getOwnership();
        return config.onlyShowOwnedDrops() && ownership!=TileItem.OWNERSHIP_SELF && ownership!=TileItem.OWNERSHIP_GROUP;
    }
    static Color color(ImprovedLootingConfig config,GroundLoot.Entry entry,Color tierColor)
    {
        Color filter=entry.display.getTextColor();
        if(!Color.WHITE.equals(filter))return filter;
        if(untradeable(entry))return config.untradeableColor()==null?new Color(0xff5555):config.untradeableColor();
        return tierColor;
    }
    static boolean tierEffects(ImprovedLootingConfig config,GroundLoot.Entry entry)
    { return config.priceTiersEnabled() && !untradeable(entry) && Color.WHITE.equals(entry.display.getTextColor()); }
    private LootDisplayOptions() {}
}

package com.improvedlooting;

import java.util.*;
import java.util.regex.*;

final class LootIconImport
{
    static List<ItemIcons.Assignment> parse(String source)
    {
        if(source.length()>1000000) { throw new IllegalArgumentException("Filter is too large."); }

        String clean=source;
        StringBuilder stripped=new StringBuilder();
        boolean quote=false;
        for(int i=0;i<clean.length();i++)
        {
            char c=clean.charAt(i);
            if(c=='"' && (i==0 || clean.charAt(i-1)!='\\')) { quote=!quote; }
            if(!quote && c=='/' && i+1<clean.length() && clean.charAt(i+1)=='/') { while(i<clean.length() && clean.charAt(i)!='\n') { i++; } stripped.append('\n'); continue; }
            if(!quote && c=='/' && i+1<clean.length() && clean.charAt(i+1)=='*') { int end=clean.indexOf("*/",i+2); if(end<0) { throw new IllegalArgumentException("Unclosed comment."); } i=end+1; continue; }
            stripped.append(c);
        }
        clean=stripped.toString();
        if(Pattern.compile("(?m)^\\s*#").matcher(clean).find()) { throw new IllegalArgumentException("This filter uses directives/macros. Automatic icon import is not supported; assign its icons manually. Nothing was changed."); }
        Pattern block=Pattern.compile("\\G\\s*(meta|rule|if|apply)\\s*(?:\\(([^{}]*)\\))?\\s*\\{([^{}]*)\\}");
        Matcher m=block.matcher(clean); int end=0;
        LinkedHashMap<String,ItemIcons.Assignment> result=new LinkedHashMap<>();
        while(m.find())
        {
            end=m.end();
            if(m.group(1).equals("meta")) { continue; }
            if(m.group(1).equals("apply")) { throw unsupported(); }
            String condition=m.group(2);
            if(condition==null) { throw unsupported(); }
            Matcher selector=Pattern.compile("\\s*(id|name)\\s*:\\s*(.*?)\\s*",Pattern.DOTALL).matcher(condition);
            if(!selector.matches()) { throw unsupported(); }
            String values=selector.group(2).trim();
            if(values.startsWith("[") && values.endsWith("]")) { values=values.substring(1,values.length()-1); }
            List<String> keys=new ArrayList<>();
            Matcher value=Pattern.compile(selector.group(1).equals("id") ? "\\G\\s*(\\d+)\\s*(?:,|$)" : "\\G\\s*\"([^\"*?\\\\]+)\"\\s*(?:,|$)").matcher(values);
            int used=0;
            while(value.find()) { keys.add(value.group(1)); used=value.end(); }
            if(keys.isEmpty() || used!=values.length()) { throw unsupported(); }
            Matcher icon=Pattern.compile("(?:^|(?<=;))\\s*icon\\s*=\\s*(CurrentItem|Item|Sprite)\\s*\\(([^()]*)\\)\\s*;",Pattern.DOTALL).matcher(m.group(3));
            if(!icon.find()) { throw new IllegalArgumentException("Every rule must have an explicit CurrentItem(), Item(id), or Sprite(id,index) icon. File icons and rules without icons cannot be transferred safely."); }
            String type=icon.group(1), args=icon.group(2).trim();
            int iconId=0,index=0;
            if(type.equals("CurrentItem")) { if(!args.isEmpty()) { throw unsupported(); } }
            else
            {
                if(!args.matches(type.equals("Item") ? "\\d+" : "\\d+\\s*,\\s*\\d+")) { throw unsupported(); }
                String[] parts=args.split("\\s*,\\s*");
                try { iconId=Integer.parseInt(parts[0]); if(parts.length>1) { index=Integer.parseInt(parts[1]); } }
                catch(NumberFormatException e) { throw unsupported(); }
            }
            if(icon.find()) { throw new IllegalArgumentException("Multiple icon assignments in a rule are not supported."); }
            for(String key:keys)
            {
                ItemIcons.Assignment a=new ItemIcons.Assignment();
                try { if(selector.group(1).equals("id")) { a.itemId=Integer.parseInt(key); } else { a.name=key; } }
                catch(NumberFormatException e) { throw unsupported(); }
                a.kind=type.equals("CurrentItem") ? ItemIcons.Kind.CURRENT_ITEM : type.equals("Item") ? ItemIcons.Kind.ITEM : ItemIcons.Kind.SPRITE;
                a.iconId=iconId; a.spriteIndex=index;
                if(a.itemId>100000 || iconId>100000 || index>255 || result.size()>=500) { throw unsupported(); }

                if(!result.isEmpty() && result.values().iterator().next().itemId>=0 != (a.itemId>=0)) { throw new IllegalArgumentException("Mixed name and ID rules need manual review; nothing was imported."); }
                result.putIfAbsent(a.key(),a);
            }
        }
        if(!clean.substring(end).trim().isEmpty() || result.isEmpty()) { throw unsupported(); }
        return new ArrayList<>(result.values());
    }
    private static IllegalArgumentException unsupported()
    { return new IllegalArgumentException("Only terminal rules with exact item IDs or names are supported. Conditional, wildcard, inherited or malformed rules require manual assignments. Nothing was changed."); }
}

package com.improvedlooting;

import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.MouseAdapter;

@Singleton
final class LootLabelInput extends MouseAdapter
{
    @Inject Client client;
    @Inject ClientThread thread;
    @Inject GroundLoot loot;
    @Inject LootPreferences preferences;
    private volatile Frame displayed=new Frame(Collections.emptyList(),0,0);
    private final List<Hit> frame=new ArrayList<>();
    private volatile long generation;
    private volatile boolean active;
    private long frameGeneration;
    private Hit pressed;
    private int pressX,pressY;
    private long pressGeneration;
    private boolean consumeClick;

    void start(){active=true;reset();}
    void stop(){active=false;reset();}
    synchronized void reset(){generation++;displayed=new Frame(Collections.emptyList(),generation,0);}

    void beginFrame(){frameGeneration=generation;frame.clear();}
    void add(Rectangle bounds,GroundLoot.Entry entry,boolean hidden){frame.add(new Hit(bounds,entry.item.getId(),hidden));}
    synchronized void finishFrame(){if(active && frameGeneration==generation)displayed=new Frame(Collections.unmodifiableList(new ArrayList<>(frame)),generation,System.nanoTime());}

    @Override public MouseEvent mousePressed(MouseEvent event)
    {
        pressed=null;consumeClick=false;
        Frame snapshot=displayed;
        if(!active || event.isConsumed() || event.getButton()!=MouseEvent.BUTTON1 || !event.isAltDown()
            || snapshot.generation!=generation || System.nanoTime()-snapshot.renderedAt>500_000_000L)return event;

        for(int i=snapshot.hits.size()-1;i>=0;i--) {
            Hit hit=snapshot.hits.get(i);if(!hit.bounds.contains(event.getPoint()))continue;
            pressed=hit;pressX=event.getX();pressY=event.getY();pressGeneration=snapshot.generation;
            consumeClick=true;event.consume();break;
        }
        return event;
    }
    @Override public MouseEvent mouseDragged(MouseEvent event)
    {
        if(consumeClick) {
            event.consume();
            if(Math.abs(event.getX()-pressX)>5 || Math.abs(event.getY()-pressY)>5)pressed=null;
        }
        return event;
    }
    @Override public MouseEvent mouseExited(MouseEvent event){pressed=null;return event;}
    @Override public MouseEvent mouseReleased(MouseEvent event)
    {
        if(!consumeClick || event.getButton()!=MouseEvent.BUTTON1)return event;
        event.consume();Hit hit=pressed;pressed=null;long token=pressGeneration;
        if(hit!=null && Math.abs(event.getX()-pressX)<=5 && Math.abs(event.getY()-pressY)<=5)
            thread.invokeLater(()->{
                if(active && token==generation && loot.groundAllowed() && client.getGameState()==GameState.LOGGED_IN && !client.isMenuOpen()) {
                    preferences.labelHidden(hit.id,!hit.hidden);
                    reset();
                }
            });
        return event;
    }
    @Override public MouseEvent mouseClicked(MouseEvent event)
    {
        if(consumeClick && event.getButton()==MouseEvent.BUTTON1){event.consume();consumeClick=false;}
        return event;
    }
    private static final class Hit {
        final Rectangle bounds;final int id;final boolean hidden;
        Hit(Rectangle bounds,int id,boolean hidden){this.bounds=new Rectangle(bounds);this.id=id;this.hidden=hidden;}
    }
    private static final class Frame {
        final List<Hit> hits;final long generation,renderedAt;
        Frame(List<Hit> hits,long generation,long renderedAt){this.hits=hits;this.generation=generation;this.renderedAt=renderedAt;}
    }
}

