package com.improvedlooting;

import com.improvedlooting.rs2f.model.ItemFacts;
import java.util.*;
import net.runelite.api.*;
import net.runelite.api.events.MenuOpened;
import java.util.function.Function;
import java.util.function.Predicate;
import net.runelite.client.util.Text;

final class LootPileOrder {
    private LootPileOrder() {}

    static int category(ItemFacts facts) {
        if (!facts.isTradeable()) return 2;
        String name = facts.getName().toLowerCase(Locale.ROOT);
        return name.equals("bones") || name.endsWith(" bones") || name.equals("ashes") || name.endsWith(" ashes") ? 1 : 0;
    }

    static int compare(ItemFacts a, long aq, ItemFacts b, long bq) {
        return compare(a, aq, b, bq, ImprovedLootingConfig.PriceSource.GE);
    }

    static int compare(ItemFacts a, long aq, ItemFacts b, long bq, ImprovedLootingConfig.PriceSource source) {
        int category = Integer.compare(category(a), category(b));
        return category != 0 ? category : Long.compare(LootValues.value(source, b, bq), LootValues.value(source, a, aq));
    }

    static Comparator<GroundLoot.Entry> labels(Predicate<GroundLoot.Entry> hidden) {
        return labels(hidden, ImprovedLootingConfig.PriceSource.GE);
    }

    static Comparator<GroundLoot.Entry> labels(Predicate<GroundLoot.Entry> hidden, ImprovedLootingConfig.PriceSource source) {

        Map<GroundLoot.Entry, Boolean> visibility = new IdentityHashMap<>();
        return Comparator.comparing((GroundLoot.Entry e) -> visibility.computeIfAbsent(e, hidden::test))
            .thenComparing((a, b) -> compare(a.facts, a.renderQuantity, b.facts, b.renderQuantity, source));
    }

    static Map<Integer, Integer> ranks(Collection<GroundLoot.Entry> pile, Predicate<GroundLoot.Entry> hidden) {
        return ranks(pile, hidden, ImprovedLootingConfig.PriceSource.GE);
    }

    static Map<Integer, Integer> ranks(Collection<GroundLoot.Entry> pile, Predicate<GroundLoot.Entry> hidden, ImprovedLootingConfig.PriceSource source) {
        Comparator<GroundLoot.Entry> order = labels(hidden, source);
        Map<Integer, GroundLoot.Entry> best = new LinkedHashMap<>();
        for (GroundLoot.Entry entry : pile) {
            if (entry.grouped) continue;

            best.merge(entry.item.getId(), entry, (a, b) -> order.compare(a, b) <= 0 ? a : b);
        }
        List<Integer> ids = new ArrayList<>(best.keySet());
        ids.sort((a,b) -> order.compare(best.get(a), best.get(b)));
        Map<Integer,Integer> result = new HashMap<>();
        int rank = 0;
        for (int i = 0; i < ids.size(); i++) {
            int id = ids.get(i);
            if (i > 0 && order.compare(best.get(ids.get(i-1)), best.get(id)) != 0) rank = i;
            result.put(id, -rank);
        }
        return result;
    }

    static void opened(Client client, ImprovedLootingConfig config, MenuOpened event, Function<Tile, Map<Integer,Integer>> rankLookup) {
        if (!config.prioritizeLoot() || client.getGameState() != GameState.LOGGED_IN) return;
        MenuEntry[] original = client.getMenu().getMenuEntries(), sorted = original.clone();
        Map<List<Integer>, List<Integer>> piles = new LinkedHashMap<>();
        for (int i = 0; i < original.length; i++) {
            MenuEntry e = original[i];
            if (!take(e)) continue;
            List<Integer> key = Arrays.asList(e.getWorldViewId(), e.getParam0(), e.getParam1(), e.isDeprioritized() ? 1 : 0);
            piles.computeIfAbsent(key, k -> new ArrayList<>()).add(i);
        }
        for (List<Integer> slots : piles.values()) {
            if (slots.size() < 2) continue;
            MenuEntry first = original[slots.get(0)];
            WorldView view = client.getWorldView(first.getWorldViewId());
            if (view == null || view.getScene() == null) continue;
            Tile[][][] tiles = view.getScene().getTiles();
            int p = view.getPlane(), x = first.getParam0(), y = first.getParam1();
            if (tiles == null || p < 0 || p >= tiles.length || tiles[p] == null || x < 0 || x >= tiles[p].length
                || tiles[p][x] == null || y < 0 || y >= tiles[p][x].length) continue;
            Map<Integer,Integer> ranks = rankLookup.apply(tiles[p][x][y]);
            List<Integer> known = new ArrayList<>();
            List<MenuEntry> entries = new ArrayList<>();
            for (int slot : slots) if (ranks.containsKey(original[slot].getIdentifier())) { known.add(slot); entries.add(original[slot]); }
            entries.sort(Comparator.comparingInt(e -> ranks.get(e.getIdentifier())));
            for (int i = 0; i < known.size(); i++) sorted[known.get(i)] = entries.get(i);
        }
        if (!Arrays.equals(original, sorted)) { client.getMenu().setMenuEntries(sorted); if (event != null) event.setMenuEntries(sorted); }
    }

    private static boolean take(MenuEntry entry) {
        MenuAction type = entry.getType();
        return entry.onClick() == null && entry.getSubMenu() == null && !entry.isForceLeftClick()
            && (type == MenuAction.GROUND_ITEM_FIRST_OPTION || type == MenuAction.GROUND_ITEM_SECOND_OPTION
            || type == MenuAction.GROUND_ITEM_THIRD_OPTION || type == MenuAction.GROUND_ITEM_FOURTH_OPTION
            || type == MenuAction.GROUND_ITEM_FIFTH_OPTION) && "Take".equals(Text.removeTags(entry.getOption()));
    }
}

package com.improvedlooting;

import com.google.gson.Gson;
import com.improvedlooting.rs2f.DisplayConfig;
import java.awt.Color;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
final class LootPreferences
{
    static final String KEY = "lootOverridesV1";
    enum Action { FILTER, SHOW, HIDE, HIGHLIGHT }
    static final class ItemRule { Action action = Action.FILTER; String category = ""; Boolean labelHidden, hideMenu; }
    static final class Data
    {
        int version = 1;
        Map<Integer, ItemRule> items = new LinkedHashMap<>();
        Map<String, Action> sources = new LinkedHashMap<>();
    }
    @Inject ConfigManager configs;
    @Inject Gson gson;
    private String loaded;
    private Data current = new Data();
    private long revision;
    synchronized Data snapshot()
    {
        String raw = configs.getConfiguration(ImprovedLootingConfig.GROUP, KEY);
        if (!Objects.equals(raw, loaded))
        {
            loaded = raw;
            try { current = parse(raw); } catch (IllegalArgumentException ex) { current = new Data(); }
            revision++;
        }
        return current;
    }
    synchronized long revision() { snapshot(); return revision; }
    Data parse(String raw)
    {
        if (raw == null || raw.isBlank()) return new Data();
        if (raw.length() > 150000) throw new IllegalArgumentException("Too many overrides");
        try
        {
            Data data = gson.fromJson(raw, Data.class);
            if (data == null || data.version != 1 || data.items == null || data.sources == null
                || data.items.size() > 512 || data.sources.size() > 100) throw new IllegalArgumentException("Invalid overrides");
            data.items.forEach((id, rule) -> {
                if (id == null || id < 0 || id > 100000 || rule == null || rule.action == null || !validLabel(rule.category, 40))
                    throw new IllegalArgumentException("Invalid item override");
            });
            data.sources.forEach((name, action) -> {
                if (!validLabel(name, 100) || name.isBlank() || action == null) throw new IllegalArgumentException("Invalid source rule");
            });
            return data;
        }
        catch (com.google.gson.JsonParseException ex) { throw new IllegalArgumentException("Invalid overrides", ex); }
    }
    static boolean validLabel(String text, int limit)
    { return text != null && text.length() <= limit && text.chars().noneMatch(c -> Character.isISOControl(c) || c == '<' || c == '>'); }
    synchronized void set(int id, Action action, String category)
    {
        Data next = parse(gson.toJson(snapshot()));
        ItemRule rule = next.items.getOrDefault(id,new ItemRule()); rule.action = action; rule.category = category.trim();
        if (action == Action.FILTER && rule.category.isEmpty() && rule.labelHidden==null && rule.hideMenu==null) next.items.remove(id); else next.items.put(id, rule);
        save(next);
    }
    synchronized void labelHidden(int id,Boolean value)
    {
        Data next=parse(gson.toJson(snapshot()));ItemRule rule=next.items.getOrDefault(id,new ItemRule());
        rule.labelHidden=value;
        if(rule.action==Action.FILTER && rule.category.isEmpty() && value==null && rule.hideMenu==null)next.items.remove(id);else next.items.put(id,rule);
        save(next);
    }
    Boolean labelHidden(int id){ItemRule rule=snapshot().items.get(id);return rule==null?null:rule.labelHidden;}
    Boolean hideMenu(int id){ItemRule rule=snapshot().items.get(id);return rule==null?null:rule.hideMenu;}
    synchronized void hideMenu(int id,Boolean value)
    {
        Data next=parse(gson.toJson(snapshot()));ItemRule rule=next.items.getOrDefault(id,new ItemRule());
        rule.hideMenu=value;
        if(rule.action==Action.FILTER && rule.category.isEmpty() && rule.labelHidden==null && value==null)next.items.remove(id);else next.items.put(id,rule);
        save(next);
    }
    synchronized void source(String name, Action action)
    {
        Data next = parse(gson.toJson(snapshot()));
        name = name.trim();
        if (action == Action.FILTER) next.sources.remove(name); else next.sources.put(name, action);
        save(next);
    }
    private void save(Data next)
    {
        String raw = gson.toJson(next); parse(raw);
        current = next; loaded = raw; revision++;
        configs.setConfiguration(ImprovedLootingConfig.GROUP, KEY, raw);
    }
    String category(int id) { ItemRule rule = snapshot().items.get(id); return rule == null ? "" : rule.category; }
    Action action(int id, String source)
    {
        Data data = snapshot(); ItemRule rule = data.items.get(id);
        if (rule != null && rule.action != Action.FILTER) return rule.action;
        return source == null ? Action.FILTER : data.sources.getOrDefault(source, Action.FILTER);
    }
    static DisplayConfig apply(DisplayConfig display, Action action)
    {
        switch (action)
        {
            case HIDE: return display.toBuilder().hidden(true).hideOverlay(true).build();
            case SHOW: return display.toBuilder().hidden(false).hideOverlay(false).build();
            case HIGHLIGHT: return display.toBuilder().hidden(false).hideOverlay(false).textColor(Color.YELLOW)
                .highlightTile(true).tileStrokeColor(Color.YELLOW).tileFillColor(new Color(255, 220, 0, 30))
                .showLootbeam(true).lootbeamColor(Color.YELLOW).build();
            default: return display;
        }
    }
}

package com.improvedlooting;

import java.util.*;
import javax.inject.*;

@Singleton
final class LootProfiles
{
    static final String SAVED="savedLootPresetsV1", UNDO="lootSetupUndoV1";
    static final String[] BOOLEAN_KEYS={"lootOverlay","lootBeams","lootCompact","lootReveal","priceTiersEnabled","shareMenuIcons","lootNotifications","lootSounds","originalImages","alwaysShowValue","alwaysShowTimer","groupStacks","despawnWarnings","notificationCards","iconDespawnFade","cardBackground","cardBorder","cardShortPrices","cardAutoWidth","keepUntradeablesVisible","onlyShowOwnedDrops","prioritizeLoot","hideHiddenMenuItems","cardIndividualWidth","railDespawnTimer"};
    static final Map<String,int[]> NUMBERS=new LinkedHashMap<>();
    static { NUMBERS.put("labelRange",new int[]{1,64});NUMBERS.put("maxLabels",new int[]{10,1000});NUMBERS.put("labelSpacing",new int[]{0,16});NUMBERS.put("labelFontSize",new int[]{0,32});NUMBERS.put("iconSize",new int[]{12,96});NUMBERS.put("despawnSeconds",new int[]{1,120});NUMBERS.put("despawnMinimum",new int[]{0,Integer.MAX_VALUE});NUMBERS.put("alertVolume",new int[]{0,100});NUMBERS.put("soundCooldown",new int[]{0,60}); }
    static final class Setup { int version=1;Map<String,String> settings=new LinkedHashMap<>(); }
    static { NUMBERS.put("minimumLabelValue",new int[]{0,Integer.MAX_VALUE});NUMBERS.put("cardWidth",new int[]{120,2048});NUMBERS.put("cardHeight",new int[]{0,96});NUMBERS.put("cardRows",new int[]{0,20});NUMBERS.put("cardOpacity",new int[]{0,100}); }
    static final class Library { int version=1;Map<String,Setup> presets=new LinkedHashMap<>(); }
    @Inject ItemIcons icons;
    @Inject LootPreferences preferences;
    static Set<String> keys(){Set<String> keys=new LinkedHashSet<>(Arrays.asList(BOOLEAN_KEYS));keys.addAll(NUMBERS.keySet());Collections.addAll(keys,"cardTheme","cardBackgroundColor","untradeableColor","priceSource","priceDisplay","timerDisplay","groundStyle","labelOrder","labelAlignment",FilterIcons.KEY,ItemIcons.KEY,PriceTiers.KEY,SpecialDropSounds.KEY,LootPreferences.KEY);return keys;}
    Setup capture(){Setup s=new Setup();for(String key:keys())s.settings.put(key,icons.configs.getConfiguration(ImprovedLootingConfig.GROUP,key));return s;}
    String export(){return encode(capture());}
    private Setup tierCopy(Setup setup,boolean portable){Setup copy=new Setup();copy.version=setup.version;copy.settings.putAll(setup.settings);if(copy.settings.containsKey(PriceTiers.KEY)){String raw=copy.settings.get(PriceTiers.KEY);copy.settings.put(PriceTiers.KEY,portable?icons.tiers.portable(raw):icons.tiers.stored(raw));}if(copy.settings.get(SpecialDropSounds.KEY)!=null){String raw=copy.settings.get(SpecialDropSounds.KEY);copy.settings.put(SpecialDropSounds.KEY,portable?icons.tiers.specials.portable(raw):icons.tiers.specials.stored(raw));}return copy;}
    String encode(Setup setup){return json(tierCopy(setup,true));}
    String encodeStored(Setup setup){return json(tierCopy(setup,false));}
    private String json(Setup setup){String raw=icons.gson.toJson(setup);if(raw.length()>24000000)throw new IllegalArgumentException("Setup exceeds 24 MB");return raw;}
    Setup parse(String raw)
    {
        if(raw==null||raw.length()>24000000)throw new IllegalArgumentException("Setup exceeds 24 MB");
        try{Setup setup=icons.gson.fromJson(raw,Setup.class);validate(setup);return tierCopy(setup,false);}
        catch(com.google.gson.JsonParseException e){throw new IllegalArgumentException("Invalid setup backup",e);}
    }
    void validate(Setup s)
    {
        if(s==null||s.version!=1||s.settings==null||!keys().containsAll(s.settings.keySet()))throw new IllegalArgumentException("Unsupported setup or setting");
        for(Map.Entry<String,String> e:s.settings.entrySet())
        {
            String key=e.getKey(),value=e.getValue();if(value==null)continue;
            if(Arrays.asList(BOOLEAN_KEYS).contains(key)&&!value.equals("true")&&!value.equals("false"))throw new IllegalArgumentException("Invalid switch: "+key);
            if(NUMBERS.containsKey(key)){try{int n=Integer.parseInt(value);int[] bounds=NUMBERS.get(key);if(n<bounds[0]||n>bounds[1]||key.equals("labelFontSize")&&n>0&&n<8)throw new NumberFormatException();}catch(NumberFormatException ex){throw new IllegalArgumentException("Out of range: "+key);}}
            if(key.equals("priceSource"))ImprovedLootingConfig.PriceSource.valueOf(value);
            if(key.equals("labelOrder"))ImprovedLootingConfig.LabelOrder.valueOf(value);
            if(key.equals("priceDisplay") || key.equals("timerDisplay"))ImprovedLootingConfig.DetailMode.valueOf(value);
            if(key.equals("cardTheme"))ImprovedLootingConfig.CardTheme.valueOf(value);
            if(key.equals("cardBackgroundColor") || key.equals("untradeableColor")){
                try{Integer.parseInt(value);}catch(NumberFormatException ex){throw new IllegalArgumentException("Invalid color: "+key,ex);}
            }
            if(key.equals("groundStyle"))ImprovedLootingConfig.GroundStyle.valueOf(value);
            if(key.equals("labelAlignment"))ImprovedLootingConfig.LabelAlignment.valueOf(value);
            if(key.equals(FilterIcons.KEY)&&!value.isBlank())icons.filters.parse(value);
            if(key.equals(ItemIcons.KEY)&&!value.isBlank())icons.parse(value);
            if(key.equals(PriceTiers.KEY))icons.tiers.parse(value);
            if(key.equals(SpecialDropSounds.KEY))icons.tiers.specials.parse(value);
            if(key.equals(LootPreferences.KEY))preferences.parse(value);
        }
    }
    void applyValidated(Setup s,Long expectedProfile,String expectedCurrent)
    {
        if(!Objects.equals(expectedProfile,ProfileIdentity.current(icons.configs))||!Objects.equals(expectedCurrent,export()))throw new IllegalArgumentException("Profile or settings changed. Preview the setup again.");
        writeSetup(s,expectedCurrent);
    }
    void applyValidated(Setup s,Long expectedProfile,Setup before,String beforeJson)
    {
        if(!Objects.equals(expectedProfile,ProfileIdentity.current(icons.configs))||!Objects.equals(before.settings,capture().settings))throw new IllegalArgumentException("Profile or settings changed. Review the setup again.");
        writeSetup(s,beforeJson);
    }
    private void writeSetup(Setup s,String expectedCurrent)
    {
        icons.configs.setConfiguration(ImprovedLootingConfig.GROUP,UNDO,expectedCurrent);
        for(String key:keys()){String value=s.settings.get(key);if(value==null)icons.configs.unsetConfiguration(ImprovedLootingConfig.GROUP,key);else icons.configs.setConfiguration(ImprovedLootingConfig.GROUP,key,value);}
    }
    String undo(){return icons.configs.getConfiguration(ImprovedLootingConfig.GROUP,UNDO);}
    Library library()
    {
        return library(icons.configs.getConfiguration(ImprovedLootingConfig.GROUP,SAVED));
    }
    Library library(String raw)
    {
        if(raw==null||raw.isBlank())return new Library();
        if(raw.length()>24000000)throw new IllegalArgumentException("Preset library exceeds 24 MB");
        try{Library l=icons.gson.fromJson(raw,Library.class);if(l==null||l.version!=1||l.presets==null||l.presets.size()>12)throw new IllegalArgumentException("Invalid preset library");for(String name:l.presets.keySet())if(!LootPreferences.validLabel(name,60)||name.isBlank())throw new IllegalArgumentException("Invalid preset name");return l;}catch(com.google.gson.JsonParseException e){throw new IllegalArgumentException("Invalid preset library",e);}
    }
    void save(String name){name=name.trim();if(!LootPreferences.validLabel(name,60)||name.isBlank())throw new IllegalArgumentException("Use a name of 1–60 characters");Library l=library();l.presets.put(name,capture());persist(l);}
    void remove(String name){Library l=library();l.presets.remove(name);persist(l);}
    String encodeLibrary(Library l){Library stored=new Library();for(Map.Entry<String,Setup> entry:l.presets.entrySet())stored.presets.put(entry.getKey(),tierCopy(entry.getValue(),false));String raw=icons.gson.toJson(stored);if(raw.length()>24000000||l.presets.size()>12)throw new IllegalArgumentException("Keep at most 12 saved setups and 24 MB total");return raw;}
    private void persist(Library l){icons.configs.setConfiguration(ImprovedLootingConfig.GROUP,SAVED,encodeLibrary(l));}
    String starter(boolean valuable)
    {
        return starter(valuable,capture());
    }
    String starter(boolean valuable,Setup s)
    {
        FilterIcons.Bundle b=new FilterIcons.Bundle();b.compressedSource=FilterIcons.compress(valuable?
            "rule(gevalue:>=100000) {textColor=\"#ffcf60\"; icon=CurrentItem(); showValue=true; showDespawn=true; showLootbeam=true; notify=true;}\nrule(gevalue:>=1000) {showValue=true; showDespawn=true;}\nrule(true) {hideOverlay=true;}":
            "apply(true) {showValue=true; showDespawn=true; icon=CurrentItem();}\nrule(gevalue:>=100000) {textColor=\"#ffcf60\"; showLootbeam=true;}");
        if ("HIGH_ALCHEMY".equals(s.settings.get("priceSource"))) b.compressedSource=FilterIcons.compress(FilterIcons.source(b).replace("gevalue:","havalue:"));
        s.settings.put(FilterIcons.KEY,icons.gson.toJson(b));s.settings.put(LootPreferences.KEY,null);return icons.gson.toJson(s);
    }
    String groundItemsPreview()
    {
        String highlights=icons.configs.getConfiguration("grounditems","highlightedItems"),hidden=icons.configs.getConfiguration("grounditems","hiddenItems");
        return groundItemsPreview(capture(),highlights,hidden);
    }
    String groundItemsPreview(Setup s,String highlights,String hidden)
    {
        if((highlights==null||highlights.isBlank())&&(hidden==null||hidden.isBlank()))throw new IllegalArgumentException("No Ground Items highlight / hide lists found in this profile");
        StringBuilder rules=new StringBuilder("apply(true) {showValue=true; showDespawn=true;}\n");
        appendNames(rules,highlights,"hidden=false; hideOverlay=false; textColor=\"#ffcf60\"; showLootbeam=true;");
        appendNames(rules,hidden,"hidden=true; hideOverlay=true;");
        FilterIcons.Bundle bundle=new FilterIcons.Bundle();bundle.compressedSource=FilterIcons.compress(rules.toString());s.settings.put(FilterIcons.KEY,icons.gson.toJson(bundle));return icons.gson.toJson(s);
    }
    private static void appendNames(StringBuilder rules,String names,String display)
    {
        if(names==null)return;if(names.length()>100000)throw new IllegalArgumentException("Item list too large");
        for(String name:names.split(",")){name=name.trim();if(name.isEmpty())continue;FilterEditor.rule(name,0,0);rules.append("rule(name:\"").append(name).append("\") {").append(display).append("}\n");}
    }
}

package com.improvedlooting;

import java.awt.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.Callable;
import java.util.function.Consumer;
import javax.swing.*;
import net.runelite.client.util.Filepath;

final class LootProfilesEditor
{
    private final LootProfiles profiles;
    private final Long profile;
    private final JComboBox<String> saved=new JComboBox<>();
    private final JTextField name=new JTextField(22);
    private final JComboBox<String> starter=new JComboBox<>(new String[]{"Show all loot", "Valuable loot", "Ground Items hide / highlight lists"});
    private final JTextArea summary=help("Choose a file, saved setup or starter to review. Nothing changes until you apply it.");
    private final JTextArea status=help(" ");
    private final java.util.List<JComponent> controls=new ArrayList<>();
    private JButton apply,delete;
    private JDialog dialog;
    private boolean closed,busy,confirmDelete;
    private int revision;
    private Review pending;

    private static final class Review
    {
        final LootProfiles.Setup setup,before;
        final String beforeJson,label;
        Review(LootProfiles.Setup setup,LootProfiles.Setup before,String beforeJson,String label){this.setup=setup;this.before=before;this.beforeJson=beforeJson;this.label=label;}
    }

    LootProfilesEditor(LootProfiles profiles){this.profiles=profiles;profile=ProfileIdentity.current(profiles.icons.configs);}
    void open(Component owner)
    {
        if(dialog!=null&&dialog.isDisplayable()){dialog.toFront();return;}
        dialog=new JDialog(SwingUtilities.getWindowAncestor(owner),"Settings — Improved Looting",Dialog.ModalityType.MODELESS);
        dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);dialog.setContentPane(build());
        dialog.setMinimumSize(new Dimension(600,520));dialog.setSize(680,570);dialog.setLocationRelativeTo(owner);
        dialog.addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosed(java.awt.event.WindowEvent e){close();}});
        dialog.setVisible(true);
    }
    boolean isOpen(){return !closed&&dialog!=null&&dialog.isDisplayable();}

    JPanel build()
    {
        JPanel root=new JPanel(new BorderLayout(8,10));root.setBorder(BorderFactory.createEmptyBorder(12,12,12,12));
        JPanel sections=new JPanel();sections.setLayout(new BoxLayout(sections,BoxLayout.Y_AXIS));
        JPanel transfer=section("Transfer settings");
        JTextArea instructions=help("Export a file, switch to the destination account / RuneLite profile, then import it here. Includes rules, tiers, sounds, images and item choices.");instructions.setRows(3);transfer.add(instructions);
        JPanel files=row();button(files,"Export settings…",this::chooseExport);button(files,"Import settings…",this::chooseImport);transfer.add(files);sections.add(transfer);

        JPanel setups=section("Saved setups");
        JPanel current=row();current.add(new JLabel("Name"));name.getAccessibleContext().setAccessibleName("Setup name");current.add(name);controls.add(name);
        button(current,"Save current",()->changeSaved(false));setups.add(current);
        JPanel stored=row();saved.setPreferredSize(new Dimension(260,28));saved.getAccessibleContext().setAccessibleName("Saved setups");stored.add(saved);controls.add(saved);
        button(stored,"Review",()->{String selected=(String)saved.getSelectedItem();if(selected==null)throw new IllegalArgumentException("Save a setup first.");String raw=libraryRaw();review(selected,()->profiles.encode(profiles.library(raw).presets.get(selected)));});
        delete=button(stored,"Delete",()->{if(!confirmDelete){confirmDelete=true;delete.setText("Confirm delete");status.setText("Click Confirm delete to remove this saved setup. Current settings are retained.");}else changeSaved(true);});
        saved.addActionListener(e->{confirmDelete=false;if(delete!=null)delete.setText("Delete");});setups.add(stored);sections.add(setups);

        JPanel starters=section("Start from");JPanel source=row();starter.setPreferredSize(new Dimension(330,28));source.add(starter);controls.add(starter);
        button(source,"Review starter",this::reviewStarter);starters.add(source);sections.add(starters);
        root.add(sections,BorderLayout.NORTH);
        JPanel review=section("Review");summary.setRows(4);summary.getAccessibleContext().setAccessibleName("Setup review");review.add(summary);
        JPanel actions=row();apply=button(actions,"Apply reviewed setup",this::applyReviewed);apply.setEnabled(false);
        button(actions,"Undo last change",()->{String raw=profiles.undo();if(raw==null)throw new IllegalArgumentException("No setup change to undo.");review("Undo last change",()->raw);});review.add(actions);root.add(review,BorderLayout.CENTER);
        status.setRows(2);status.getAccessibleContext().setAccessibleName("Settings status");root.add(status,BorderLayout.SOUTH);
        String raw=libraryRaw();background("Loading saved setups…",()->profiles.library(raw),library->{refresh(library);status.setText("Ready. Imported and saved setups are reviewed before applying.");});
        return root;
    }

    private void chooseExport()
    {
        java.util.List<Filepath> files=new Filepath.Chooser().setIsSave().setAcceptsFiles().setDialogTitle("Export Looting settings")
            .setFileName("improved-looting-settings.json").setDefaultExtension("json").addExtensionFilter("Looting settings", "json").showDialog(dialog);
        if(files!=null&&!files.isEmpty()&&valid())exportTo(files.get(0));
    }
    void exportTo(Filepath file)
    {
        if(!valid()||busy)return;LootProfiles.Setup snapshot=profiles.capture();
        background("Exporting settings… You can keep playing.",()->{
            String raw=profiles.encode(snapshot);

            try(Writer writer=file.openBufferedWriter(java.nio.file.StandardOpenOption.CREATE_NEW,java.nio.file.StandardOpenOption.WRITE)){writer.write(raw);}
            return raw.length();
        },size->status.setText("Settings exported ("+size+" characters). Import this file in the destination profile."));
    }
    private void chooseImport()
    {
        java.util.List<Filepath> files=new Filepath.Chooser().setIsOpen().setAcceptsFiles().setDialogTitle("Import Looting settings")
            .addExtensionFilter("Looting settings", "json", "txt").showDialog(dialog);
        if(files!=null&&!files.isEmpty()&&valid())importFrom(files.get(0));
    }
    void importFrom(Filepath file){review("Imported settings",()->{try(Reader reader=file.openBufferedReader()){return read(reader);}});}
    static String read(Reader reader)throws IOException
    {
        StringBuilder raw=new StringBuilder();char[] buffer=new char[8192];int count;
        while((count=reader.read(buffer))!=-1){if(raw.length()+count>24000000)throw new IllegalArgumentException("Setup exceeds 24 MB");raw.append(buffer,0,count);}
        return raw.toString();
    }
    private void reviewStarter()
    {
        int selected=starter.getSelectedIndex();LootProfiles.Setup snapshot=profiles.capture();
        String highlights=profiles.icons.configs.getConfiguration("grounditems","highlightedItems"),hidden=profiles.icons.configs.getConfiguration("grounditems","hiddenItems");
        review((String)starter.getSelectedItem(),()->selected==2?profiles.groundItemsPreview(snapshot,highlights,hidden):profiles.starter(selected==1,snapshot));
    }
    void review(String label,Callable<String> source)
    {
        if(!valid()||busy)return;LootProfiles.Setup before=profiles.capture();pending=null;
        background("Checking settings, rules, images and sounds…",()->new Review(profiles.parse(source.call()),before,profiles.encodeStored(before),label),ready->{
            pending=ready;apply.setEnabled(true);
            summary.setText(ready.label+"\nReady to replace this profile's Looting settings, rules, tiers, sounds, images and item choices. Missing options return to their defaults.\nUndo keeps the complete previous setup.");
            status.setText("Ready to apply. Current settings have not changed.");
        });
    }
    private void applyReviewed()
    {
        if(pending==null)return;
        profiles.applyValidated(pending.setup,profile,pending.before,pending.beforeJson);pending=null;apply.setEnabled(false);
        summary.setText("Setup applied. Use Undo last change to review and restore the previous setup.");status.setText("Settings applied to this profile.");
    }
    private String libraryRaw(){return profiles.icons.configs.getConfiguration(ImprovedLootingConfig.GROUP,LootProfiles.SAVED);}
    private void changeSaved(boolean remove)
    {
        String selected=remove?(String)saved.getSelectedItem():name.getText().trim();
        if(selected==null||selected.isBlank()||!LootPreferences.validLabel(selected,60))throw new IllegalArgumentException("Enter a setup name of 1–60 characters.");
        String previous=libraryRaw();LootProfiles.Setup snapshot=profiles.capture();
        background(remove?"Removing saved setup…":"Saving current setup…",()->{
            LootProfiles.Library library=profiles.library(previous);if(remove)library.presets.remove(selected);else library.presets.put(selected,snapshot);
            return profiles.encodeLibrary(library);
        },raw->{
            if(!Objects.equals(previous,libraryRaw()))throw new IllegalArgumentException("Saved setups changed. Reopen Settings and try again.");
            profiles.icons.configs.setConfiguration(ImprovedLootingConfig.GROUP,LootProfiles.SAVED,raw);

            if(remove)saved.removeItem(selected);else{boolean exists=false;for(int i=0;i<saved.getItemCount();i++)exists|=selected.equals(saved.getItemAt(i));if(!exists)saved.addItem(selected);saved.setSelectedItem(selected);}
            confirmDelete=false;delete.setText("Delete");status.setText(remove?"Saved setup removed. Current settings are retained.":"Current setup saved. Use Export settings to move it to another profile.");
        });
    }
    private void refresh(LootProfiles.Library library){saved.removeAllItems();for(String key:library.presets.keySet())saved.addItem(key);}
    private boolean valid()
    {
        if(closed)return false;
        if(!Objects.equals(profile,ProfileIdentity.current(profiles.icons.configs))){pending=null;apply.setEnabled(false);status.setText("Profile changed. Close and reopen Settings in the intended profile.");return false;}
        return true;
    }
    private <T> void background(String message,Callable<T> work,Consumer<T> done)
    {
        if(!valid()||busy)return;busy=true;int token=++revision;controls.forEach(c->c.setEnabled(false));status.setText(message);
        new SwingWorker<T,Void>(){
            protected T doInBackground()throws Exception{return work.call();}
            protected void done(){
                if(closed||token!=revision)return;busy=false;controls.forEach(c->c.setEnabled(true));apply.setEnabled(pending!=null);
                if(!valid())return;try{done.accept(get());}catch(Exception e){Throwable cause=e.getCause()==null?e:e.getCause();if(cause instanceof java.nio.file.FileAlreadyExistsException)status.setText("That file already exists. Export again with a new name to keep both backups.");else error(cause);}
            }
        }.execute();
    }
    private JButton button(JPanel parent,String label,Runnable action)
    {
        JButton button=new JButton(label);controls.add(button);button.addActionListener(e->{if(!valid()||busy)return;try{action.run();}catch(Exception ex){error(ex);}});parent.add(button);return button;
    }
    private void error(Throwable error){status.setText("Not changed: "+error.getMessage());}
    private static JPanel row(){return new JPanel(new FlowLayout(FlowLayout.LEFT,6,4));}
    private static JPanel section(String label){JPanel panel=new JPanel();panel.setLayout(new BoxLayout(panel,BoxLayout.Y_AXIS));panel.setBorder(BorderFactory.createTitledBorder(label));return panel;}
    private static JTextArea help(String text){JTextArea area=new JTextArea(text);area.setEditable(false);area.setOpaque(false);area.setLineWrap(true);area.setWrapStyleWord(true);area.setColumns(45);return area;}
    void close(){closed=true;revision++;pending=null;if(dialog!=null&&dialog.isDisplayable())dialog.dispose();}
}

package com.improvedlooting;

import com.improvedlooting.rs2f.DisplayConfig;
import com.improvedlooting.rs2f.FilterRule;
import com.improvedlooting.rs2f.model.ItemFacts;
import java.util.*;

final class LootResolution
{
    static DisplayConfig resolve(FilterIcons.Prepared filter, ItemFacts facts, LootPreferences preferences, String source)
    {
        DisplayConfig display = filter.program.evaluate(facts);
        return preferences == null ? display : LootPreferences.apply(display, preferences.action(facts.getId(), source));
    }
    static int secondsRemaining(int despawnTick, int currentTick)
    { return despawnTick <= 0 ? -1 : (int)Math.max(0, (((long)despawnTick - currentTick) * 3 + 4) / 5); }
    static String explain(FilterIcons.Prepared filter, ItemFacts facts, DisplayConfig finalDisplay,
        LootPreferences.Action override, String source, int seconds)
    {
        return explain(filter, facts, finalDisplay, override, source, seconds, ImprovedLootingConfig.PriceSource.GE);
    }
    static String explain(FilterIcons.Prepared filter, ItemFacts facts, DisplayConfig finalDisplay,
        LootPreferences.Action override, String source, int seconds, ImprovedLootingConfig.PriceSource prices)
    {
        StringBuilder out = new StringBuilder();
        out.append(facts.getName()).append(" (#").append(facts.getId()).append(")\n")
            .append("Quantity: ").append(facts.getQuantity()).append(prices == ImprovedLootingConfig.PriceSource.HIGH_ALCHEMY ? "\nStack High Alchemy value: " : "\nStack GE value: ")
            .append(LootValues.value(prices, facts, facts.getQuantity())).append(" gp\n")
            .append("Ownership: ").append(ownership(facts.getOwnership())).append("\n")
            .append("Source: ").append(source == null ? "Unavailable: RuneLite does not identify each pile’s monster source" : source + " (server loot event)").append("\n")
            .append("Despawn: ").append(seconds < 0 ? "Unknown; not supplied by client" : seconds + " seconds").append("\n\nRule evaluation, highest priority first:\n");
        int index = 0, matched = 0;
        for (FilterRule rule : filter.program.rules)
        {
            index++;
            if (!rule.getCond().test(null, facts)) continue;
            matched++;
            out.append('#').append(index).append(" matched, source line ").append(filter.userLine(rule.getSourceLine()))
                .append(rule.isTerminal() ? " — final matching rule\n" : " — apply and continue\n");
            if (rule.isTerminal()) break;
            if (matched >= 100) { out.append("Further matching rules omitted from this explanation.\n"); break; }
        }
        if (matched == 0) out.append("No matching rule; default visible white label.\n");
        out.append("\nManual/source override: ").append(override).append("\nFinal result:\n")
            .append("Label: ").append(finalDisplay.isHideOverlay() ? "hidden" : "visible")
            .append("\nHidden item rule: ").append(finalDisplay.isHidden())
            .append("\nColor: ").append(String.format("#%06X", finalDisplay.getTextColor().getRGB() & 0xffffff))
            .append("\nIcon: ").append(finalDisplay.getIcon() == null ? "none" : finalDisplay.getIcon())
            .append("\nBeam rule: ").append(finalDisplay.isShowLootbeam())
            .append("\nNotification rule: ").append(finalDisplay.isNotify())
            .append("\nSound rule: ").append(finalDisplay.getSound() == null ? "silent" : finalDisplay.getSound())
            .append("\nMenu priority: ").append(finalDisplay.getMenuSort())
            .append("\n\nAppearance, tier beam settings, seven-tier effects and master alert switches also apply. Hidden drops never alert.\n");
        return out.toString();
    }
    private static String ownership(int value)
    {
        switch (value) { case 1: return "Yours"; case 2: return "Other player"; case 3: return "Group"; default: return "Public/unassigned"; }
    }
    private LootResolution() { }
}

