    private void error(Exception e){JOptionPane.showMessageDialog(this,e.getCause()==null?e.getMessage():e.getCause().getMessage(),"Sound unavailable",JOptionPane.WARNING_MESSAGE);}
}

package com.improvedlooting;

import java.awt.*;
import java.io.ByteArrayInputStream;
import java.util.*;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Function;
import javax.swing.*;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.util.Filepath;

final class SpecialDropEditor
{
    private final SpecialDropSounds store;
    private final PriceTiers tiers;
    private final AudioPlayer audio;
    private final Function<Component, Filepath> chooser;
    private final AtomicBoolean playing = new AtomicBoolean();
    private final JTextArea status = new JTextArea(3, 70);
    private final JButton save = new JButton("Save special drops");
    private volatile boolean closed;
    private int busy;
    private final List<JSpinner> volumes = new ArrayList<>();
    private final Map<JSpinner, SpecialDropSounds.Choice> volumeChoices = new LinkedHashMap<>();

    SpecialDropEditor(SpecialDropSounds store, PriceTiers tiers, AudioPlayer audio, Function<Component, Filepath> chooser)
    { this.store = store; this.tiers = tiers; this.audio = audio; this.chooser = chooser; }

    JPanel build(Component owner)
    {
        JPanel root = new JPanel(new BorderLayout(8, 8));
        root.setBorder(BorderFactory.createEmptyBorder(12, 12, 12, 12));
        SpecialDropSounds.Ready current = store.snapshot();
        if (current == null) { root.add(new JLabel(store.status()), BorderLayout.NORTH); return root; }
        SpecialDropSounds.Setup draft = store.copy(current.setup);
        Long profile = ProfileIdentity.current(store.configs); String[] before = {store.raw()};
        root.add(new JLabel("<html><b>Special drops</b><br>Priority: Pet → Collection log → Item override → Clue difficulty → Untradeable → Price tier.<br>Enable Drop sounds. Volume is a percentage of your main sound volume. Silent stops lower-priority sounds.<br>Collection-log alerts need the game's chat or popup notification enabled. Pet/log sounds bypass the ordinary cooldown.</html>"), BorderLayout.NORTH);
        JPanel body = new JPanel(); body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
        for (SpecialDropSounds.Kind kind : SpecialDropSounds.Kind.values())
            body.add(row(owner, kind.label, draft.categories.get(kind), null));
        JPanel items = new JPanel(); items.setLayout(new BoxLayout(items, BoxLayout.Y_AXIS));
        for (Map.Entry<String, SpecialDropSounds.Choice> item : draft.items.entrySet())
            addItem(items, owner, draft, item.getKey(), item.getValue());
        JPanel add = new JPanel(new FlowLayout(FlowLayout.LEFT));
        JTextField name = new JTextField(25); name.getAccessibleContext().setAccessibleName("Exact item name");
        JButton addItem = new JButton("Add item override");
        add.add(new JLabel("Exact item name")); add.add(name); add.add(addItem);
        addItem.addActionListener(e -> {
            String value = name.getText().trim();
            if (!LootPreferences.validLabel(value, 100) || value.isBlank()) { status.setText("Enter the exact item name (1–100 characters)."); return; }
            if (draft.items.size() >= 128) { status.setText("Keep at most 128 item overrides."); return; }
            if (draft.items.keySet().stream().anyMatch(key -> SpecialDropSounds.itemKey(key).equals(SpecialDropSounds.itemKey(value))))
            { status.setText("That item already has an override."); return; }
            SpecialDropSounds.Choice choice = new SpecialDropSounds.Choice(); draft.items.put(value, choice);
            addItem(items, owner, draft, value, choice); items.revalidate(); items.repaint(); name.setText("");
        });
        body.add(add); body.add(items);
        JScrollPane scroll = new JScrollPane(body); scroll.getVerticalScrollBar().setUnitIncrement(24);
        root.add(scroll, BorderLayout.CENTER);
        status.setLineWrap(true); status.setWrapStyleWord(true); status.setEditable(false); status.setOpaque(false);
        status.setText(current.status.isEmpty() ? "Save special drops separately; your price tiers are unchanged. Files stay on this computer; settings exports include them. WAV, AIFF or AU, up to 15 seconds / 1 MB each." : current.status);
        JPanel footer = new JPanel(new BorderLayout(8, 8)); footer.add(status, BorderLayout.CENTER); footer.add(save, BorderLayout.EAST); root.add(footer, BorderLayout.SOUTH);
        save.addActionListener(e -> {
            try { for (JSpinner spinner : volumes) { spinner.commitEdit(); volumeChoices.get(spinner).volume = ((Number) spinner.getValue()).intValue(); } }
            catch (java.text.ParseException ex) { error(ex); return; }
            SpecialDropSounds.Setup captured = store.copy(draft); begin();
            new SwingWorker<SpecialDropSounds.Ready, Void>()
            {
                protected SpecialDropSounds.Ready doInBackground() { return store.prepareForSave(captured); }
                protected void done()
                {
                    end(); if (closed) return;
                    try
                    {
                        SpecialDropSounds.Ready ready = get();
                        if (!Objects.equals(profile, ProfileIdentity.current(store.configs)) || !Objects.equals(before[0], store.raw()))
                            throw new IllegalArgumentException("Profile or special drops changed elsewhere. Reopen the editor.");
                        store.save(ready); before[0] = store.raw();
                        status.setText(ready.status.isEmpty() ? "Special drops saved." : "Saved. " + ready.status);
                    }
                    catch (Exception ex) { error(ex); }
                }
            }.execute();
        });
        return root;
    }
    private void addItem(JPanel items, Component owner, SpecialDropSounds.Setup draft, String name, SpecialDropSounds.Choice choice)
    {
        JPanel[] holder = new JPanel[1];
        holder[0] = row(owner, name, choice, () -> { draft.items.remove(name); volumes.removeIf(v -> volumeChoices.get(v) == choice); volumeChoices.values().removeIf(c -> c == choice); items.remove(holder[0]); items.revalidate(); items.repaint(); });
        items.add(holder[0]);
    }
    private JPanel row(Component owner, String label, SpecialDropSounds.Choice choice, Runnable remove)
    {
        JPanel row = new JPanel(new BorderLayout(6, 3));
        row.setBorder(BorderFactory.createTitledBorder(label)); row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 104));
        JPanel controls = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));
        JComboBox<SpecialDropSounds.Mode> mode = new JComboBox<>(SpecialDropSounds.Mode.values());
        mode.setSelectedItem(choice.mode); mode.getAccessibleContext().setAccessibleName(label + " sound");
        JComboBox<String> tier = new JComboBox<>(new String[]{"Tier 1", "Tier 2", "Tier 3", "Tier 4", "Tier 5", "Tier 6", "Tier 7"});
        tier.setSelectedIndex(choice.tier - 1); tier.getAccessibleContext().setAccessibleName(label + " tier");
        JSpinner volume = new JSpinner(new SpinnerNumberModel(choice.volume, 0, 100, 5));
        volume.getAccessibleContext().setAccessibleName(label + " volume"); volumes.add(volume); volumeChoices.put(volume, choice);
        JButton choose = new JButton(choice.audio == null ? "Choose file" : "Replace file");
        JButton preview = new JButton("Preview"), clear = new JButton("Clear");
        JLabel filename = new JLabel(); filename.getAccessibleContext().setAccessibleName(label + " file");
        Runnable update = () -> {
            tier.setEnabled(choice.mode == SpecialDropSounds.Mode.TIER);
            filename.setText(choice.name == null ? "No custom file" : choice.name); filename.setToolTipText(choice.name);
            choose.setText(choice.audio == null ? "Choose file" : "Replace file");
            preview.setEnabled(choice.mode == SpecialDropSounds.Mode.TIER || choice.mode == SpecialDropSounds.Mode.CUSTOM && choice.audio != null);
        };
        mode.addActionListener(e -> { choice.mode = (SpecialDropSounds.Mode) mode.getSelectedItem(); update.run(); });
        tier.addActionListener(e -> choice.tier = tier.getSelectedIndex() + 1);
        volume.addChangeListener(e -> choice.volume = ((Number) volume.getValue()).intValue());
        choose.addActionListener(e -> {
            Filepath selected = chooser.apply(owner); if (selected == null) return; begin(); choose.setEnabled(false);
            new SwingWorker<String, Void>()
            {
                protected String doInBackground() throws Exception { return FilterSounds.read(selected); }
                protected void done()
                {
                    end(); if (closed) return; choose.setEnabled(true);
                    try { choice.audio = get(); choice.name = selected.getFileName(); choice.mode = SpecialDropSounds.Mode.CUSTOM; mode.setSelectedItem(choice.mode); update.run(); status.setText("Sound ready; save special drops to apply."); }
                    catch (Exception ex) { error(ex); }
                }
            }.execute();
        });
        clear.addActionListener(e -> { choice.audio = null; choice.name = null; choice.mode = SpecialDropSounds.Mode.INHERIT; mode.setSelectedItem(choice.mode); update.run(); });
        preview.addActionListener(e -> {
            if (!playing.compareAndSet(false, true)) return;
            SpecialDropSounds.Mode selectedMode = choice.mode; int selectedTier = choice.tier; String selectedAudio = choice.audio;
            int percent = choice.volume; PriceTiers.Ready price = tiers.snapshot(); preview.setEnabled(false);
            new SwingWorker<Void, Void>()
            {
                protected Void doInBackground() throws Exception
                {
                    byte[] bytes = selectedMode == SpecialDropSounds.Mode.CUSTOM && selectedAudio != null ? store.decode(selectedAudio)
                        : selectedMode == SpecialDropSounds.Mode.TIER && price != null && price.setup.tiers[selectedTier - 1].sound == PriceTiers.Sound.CUSTOM ? price.audio[selectedTier - 1] : null;
                    if (bytes == null) throw new IllegalArgumentException("The selected tier has no custom sound. Filter sound uses the matching drop's rule; Silent plays nothing.");
                    if (!closed) audio.play(new ByteArrayInputStream(bytes), LootAlerts.gain(volume() * percent / 100)); return null;
                }
                protected void done() { playing.set(false); if (closed) return; update.run(); try { get(); } catch (Exception ex) { error(ex); } }
            }.execute();
        });
        controls.add(mode); controls.add(tier); controls.add(new JLabel("Volume %")); controls.add(volume);
        JPanel files = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0)); files.add(choose); files.add(preview); files.add(clear);
        JPanel fileRow = new JPanel(new BorderLayout(6, 0)); fileRow.add(files, BorderLayout.WEST); fileRow.add(filename, BorderLayout.CENTER);
        if (remove != null) { JButton delete = new JButton("Remove"); delete.addActionListener(e -> remove.run()); controls.add(delete); }
        row.add(controls, BorderLayout.NORTH); row.add(fileRow, BorderLayout.SOUTH); update.run(); return row;
    }
    private int volume()
    {
        String raw = store.configs.getConfiguration(ImprovedLootingConfig.GROUP, "alertVolume");
        try { return raw == null ? 80 : LootAlerts.clamp(Integer.parseInt(raw), 0, 100); } catch (NumberFormatException e) { return 80; }
    }
    private void begin() { busy++; save.setEnabled(false); }
    private void end() { busy--; if (!closed) save.setEnabled(busy == 0); }
    private void error(Exception ex) { status.setText("Not saved: " + (ex.getCause() == null ? ex.getMessage() : ex.getCause().getMessage())); }
    void close() { closed = true; }
}

package com.improvedlooting;

import com.google.gson.Gson;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
final class SpecialDropSounds
{
    static final String KEY = "specialDropSoundsV1";
    enum Kind
    {
        PET("Pets"), COLLECTION_LOG("Collection-log unlocks"), UNTRADEABLE("Untradeables"),
        BEGINNER("Beginner clues"), EASY("Easy clues"), MEDIUM("Medium clues"),
        HARD("Hard clues"), ELITE("Elite clues"), MASTER("Master clues");
        final String label;
        Kind(String label) { this.label = label; }
    }
    enum Mode
    {
        INHERIT("Use next matching sound"), CUSTOM("Custom file"), TIER("Use existing tier sound"), SILENT("Silent");
        final String label;
        Mode(String label) { this.label = label; }
        public String toString() { return label; }
    }
    static final class Choice
    {
        Mode mode = Mode.INHERIT;
        int tier = 1, volume = 100;
        String audio, name;
    }
    static final class Setup
    {
        int version = 1;
        Map<Kind, Choice> categories = new EnumMap<>(Kind.class);
        Map<String, Choice> items = new LinkedHashMap<>();
    }
    static final class Ready
    {
        final Setup setup;
        final Map<String, byte[]> audio;
        final String status;
        Ready(Setup setup, Map<String, byte[]> audio, String status)
        { this.setup = setup; this.audio = audio; this.status = status; }
    }
    @Inject net.runelite.client.config.ConfigManager configs;
    @Inject Gson gson;
    @Inject TierSounds sounds;
    @Inject ScheduledExecutorService executor;
    private volatile Ready current;
    private volatile String status = "Loading special drops…";
    private long generation;

    static Setup defaults()
    {
        Setup setup = new Setup();
        for (Kind kind : Kind.values()) setup.categories.put(kind, new Choice());
        return setup;
    }
    static String itemKey(String name) { return name == null ? "" : name.trim().toLowerCase(Locale.ROOT); }
    static Kind clue(String name)
    {
        String lower = itemKey(name);
        if (!(lower.startsWith("clue scroll (") || lower.startsWith("clue bottle (")
            || lower.startsWith("clue nest (") || lower.startsWith("clue geode (")
            || lower.startsWith("clue scroll box ("))) return null;
        for (Kind kind : Kind.values())
            if (kind.ordinal() >= Kind.BEGINNER.ordinal() && lower.endsWith("(" + kind.name().toLowerCase(Locale.ROOT) + ")")) return kind;
        return null;
    }
    Setup copy(Setup setup) { return gson.fromJson(gson.toJson(setup), Setup.class); }
    private Setup settings(String raw)
    {
        if (raw == null || raw.isBlank()) return defaults();
        if (raw.length() > 12000000) throw new IllegalArgumentException("Special-drop settings exceed 12 MB.");
        try { return gson.fromJson(raw, Setup.class); }
        catch (com.google.gson.JsonParseException e) { throw new IllegalArgumentException("Invalid special-drop settings.", e); }
    }
    Ready prepare(Setup input, boolean allowMissing)
    {
        Setup setup = copy(input);
        if (setup == null || setup.version != 1 || setup.categories == null || setup.items == null
            || setup.items.size() > 128 || setup.categories.size() > Kind.values().length || setup.categories.containsKey(null))
            throw new IllegalArgumentException("Invalid special drops; keep at most 128 item overrides.");
        for (Kind kind : Kind.values()) setup.categories.putIfAbsent(kind, new Choice());
        Map<String, Choice> all = new LinkedHashMap<>();
        setup.categories.forEach((kind, choice) -> all.put(kind.label, choice));
        Set<String> names = new HashSet<>();
        setup.items.forEach((name, choice) -> {
            if (!LootPreferences.validLabel(name, 100) || name.isBlank() || !names.add(itemKey(name)))
                throw new IllegalArgumentException("Use unique, exact item names of 1–100 characters.");
            all.put("Item: " + name, choice);
        });
        Map<String, byte[]> audio = new HashMap<>();
        List<String> missing = new ArrayList<>();
        long total = 0;
        for (Map.Entry<String, Choice> entry : all.entrySet())
        {
            Choice choice = entry.getValue();
            if (choice == null || choice.mode == null || choice.tier < 1 || choice.tier > 7
                || choice.volume < 0 || choice.volume > 100 || choice.name != null
                && (choice.name.length() > 255 || choice.name.chars().anyMatch(c -> c < 32)))
                throw new IllegalArgumentException("Invalid sound choice: " + entry.getKey());
            if (choice.audio != null && !audio.containsKey(choice.audio))
            {
                try { byte[] data = decode(choice.audio); audio.put(choice.audio, data); total += data.length; }
                catch (IllegalArgumentException e)
                {
                    if (!allowMissing || !TierSounds.validReference(choice.audio)) throw e;
                    missing.add(entry.getKey());
                }
            }
            if (choice.mode == Mode.CUSTOM && choice.audio == null)
                throw new IllegalArgumentException("Choose a sound file for " + entry.getKey() + ".");
        }
        if (total > 8000000) throw new IllegalArgumentException("Special-drop sounds exceed 8 MB combined.");
        return new Ready(setup, audio, missing.isEmpty() ? "" : "Missing sound files: " + String.join(", ", missing)
            + ". Choices are retained; replace the files or import a complete settings export.");
    }
    byte[] decode(String value) { return TierSounds.reference(value) ? sounds.read(value) : FilterSounds.decode(value); }
    private Collection<Choice> choices(Setup setup)
    {
        List<Choice> all = new ArrayList<>(setup.categories.values()); all.addAll(setup.items.values()); return all;
    }
    Ready prepareForSave(Setup setup)
    {
        Ready ready = prepare(setup, true);
        Map<String, byte[]> stored = new HashMap<>();
        for (Choice choice : choices(ready.setup))
        {
            byte[] data = ready.audio.get(choice.audio);
            if (data != null) { choice.audio = sounds.store(data); stored.put(choice.audio, data); }
        }
        return new Ready(ready.setup, stored, ready.status);
    }
    Ready parse(String raw) { return prepare(settings(raw), false); }
    String stored(String raw) { return raw == null || raw.isBlank() ? raw : gson.toJson(prepareForSave(settings(raw)).setup); }
    String portable(String raw)
    {
        if (raw == null || raw.isBlank()) return raw;
        Ready ready = parse(raw);
        for (Choice choice : choices(ready.setup))
            if (choice.audio != null) choice.audio = Base64.getEncoder().encodeToString(ready.audio.get(choice.audio));
        return gson.toJson(ready.setup);
    }
    synchronized void reload()
    {
        long token = ++generation; Long profile = ProfileIdentity.current(configs); String raw = raw();
        current = null; status = "Loading special drops…";
        executor.execute(() -> {
            Ready next = null; String message;
            try { next = prepare(settings(raw), true); message = next.status; }
            catch (IllegalArgumentException e) { message = "Special drops unavailable: " + e.getMessage(); }
            synchronized (this)
            {
                if (token != generation || !Objects.equals(profile, ProfileIdentity.current(configs)) || !Objects.equals(raw, raw())) return;
                current = next; status = message;
            }
        });
    }
    synchronized void save(Ready ready)
    {
        for (Choice choice : choices(ready.setup))
            if (choice.audio != null && !TierSounds.validReference(choice.audio)) throw new IllegalArgumentException("Store sound files before saving.");
        configs.setConfiguration(ImprovedLootingConfig.GROUP, KEY, gson.toJson(ready.setup));
        generation++; current = ready; status = ready.status;
    }
    synchronized void stop() { generation++; current = null; }
    Ready snapshot() { return current; }
    String status() { return status; }
    String raw() { return configs.getConfiguration(ImprovedLootingConfig.GROUP, KEY); }
    static Choice match(Setup setup, String name, boolean pet, boolean collection, boolean untradeable)
    {
        List<Choice> candidates = new ArrayList<>();
        if (pet) candidates.add(setup.categories.get(Kind.PET));
        if (collection) candidates.add(setup.categories.get(Kind.COLLECTION_LOG));
        for (Map.Entry<String, Choice> item : setup.items.entrySet())
            if (itemKey(item.getKey()).equals(itemKey(name))) { candidates.add(item.getValue()); break; }
        Kind clue = clue(name);
        if (clue != null) candidates.add(setup.categories.get(clue));
        if (untradeable) candidates.add(setup.categories.get(Kind.UNTRADEABLE));
        for (Choice choice : candidates) if (choice != null && choice.mode != Mode.INHERIT) return choice;
        return null;
    }
}

package com.improvedlooting;

import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

@Singleton
final class SpecialLootEvents
{
    private static final String COLLECTION = "New item added to your collection log: ";
    @Inject Client client;
    @Inject LootAlerts alerts;
    private final Set<String> petNames = new HashSet<>();
    private boolean notificationStarted;

    @Subscribe public void onChatMessage(ChatMessage event)
    {
        if (client.getGameState() != GameState.LOGGED_IN
            || event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM) return;
        String message = Text.removeTags(event.getMessage());
        if (message.startsWith(COLLECTION)) collection(message.substring(COLLECTION.length()));
        else if (message.startsWith("You have a funny feeling like you're being followed")
            || message.startsWith("You feel something weird sneaking into your backpack")
            || message.startsWith("You have a funny feeling like you would have been followed"))
            alerts.special("", true, false);
    }
    @Subscribe public void onScriptPreFired(ScriptPreFired event)
    {
        if (client.getGameState() != GameState.LOGGED_IN) return;
        if (event.getScriptId() == ScriptID.NOTIFICATION_START) notificationStarted = true;
        else if (event.getScriptId() == ScriptID.NOTIFICATION_DELAY && notificationStarted)
        {
            notificationStarted = false;
            String title = client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE);
            String body = client.getVarcStrValue(VarClientID.NOTIFICATION_MAIN);
            if (title != null && body != null && Text.removeTags(title).equalsIgnoreCase("Collection log"))
            {
                String clean = Text.removeTags(body);
                if (clean.startsWith("New item:")) collection(clean.substring("New item:".length()));
            }
        }
    }
    void collection(String name)
    {
        name = name.trim();
        if (name.isEmpty() || name.length() > 100) return;
        loadPets(); alerts.special(name, petNames.contains(SpecialDropSounds.itemKey(name)), true);
    }
    private void loadPets()
    {
        if (!petNames.isEmpty()) return;
        EnumComposition pets = client.getEnum(EnumID.PETS);
        if (pets == null || pets.size() > 512) return;
        for (int i = 0; i < pets.size(); i++)
        {
            ItemComposition item = client.getItemDefinition(pets.getIntValue(i));
            if (item != null && item.getName() != null) petNames.add(SpecialDropSounds.itemKey(item.getName()));
        }
    }
    @Subscribe(priority = -1) public void onGameTick(GameTick event)
    {
        if (client.getGameState() == GameState.LOGGED_IN) { alerts.tick(); alerts.flush(); }
    }
    @Subscribe public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING
            || event.getGameState() == GameState.LOGGING_IN || event.getGameState() == GameState.CONNECTION_LOST) clear();
    }
    void clear() { notificationStarted = false; petNames.clear(); alerts.clear(); }
}

package com.improvedlooting;

import com.google.common.hash.Hashing;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.Base64;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.util.Filepath;

@Singleton
final class TierSounds
{
    private static final String PREFIX = "file:";
    interface Directory { Filepath get() throws IOException; }
    private final Directory directory;

    @Inject TierSounds(ImprovedLootingPlugin plugin) { this(plugin::soundDirectory); }
    TierSounds(Directory directory) { this.directory = directory; }

    static boolean reference(String value) { return value != null && value.startsWith(PREFIX); }
    static boolean validReference(String value) { return value != null && value.matches("file:[0-9a-f]{64}"); }

    byte[] read(String value)
    {
        if (!reference(value)) return FilterSounds.decode(value);
        if (!validReference(value)) throw new IllegalArgumentException("Invalid stored sound reference.");
        String id = value.substring(PREFIX.length());
        try (InputStream input = directory.get().joinSegment(id + ".audio").openInputStream())
        {
            byte[] data = input.readNBytes(1000001);
            if (!Hashing.sha256().hashBytes(data).toString().equals(id)) throw new IOException("Stored sound changed");
            FilterSounds.decode(Base64.getEncoder().encodeToString(data));
            return data;
        }
        catch (IOException e) { throw new IllegalArgumentException("Stored sound unavailable. Choose its file again or import a settings export containing it.", e); }
    }

    synchronized String store(byte[] data)
    {
        String id = Hashing.sha256().hashBytes(data).toString();
        Filepath temporary = null;
        try
        {
            Filepath root = directory.get();
            root.createDirectories();
            Filepath target = root.joinSegment(id + ".audio");
            if (target.exists())
            {
                try { read(PREFIX + id); return PREFIX + id; }
                catch (IllegalArgumentException ignored) { }
            }
            temporary = root.createTempFile("sound-", ".tmp");
            temporary.write(data);
            try { temporary.moveTo(target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING); }
            catch (AtomicMoveNotSupportedException e) { temporary.moveTo(target, StandardCopyOption.REPLACE_EXISTING); }
            read(PREFIX + id);
            return PREFIX + id;
        }
        catch (IOException e) { throw new IllegalArgumentException("Could not save the sound. Your previous tier settings are unchanged.", e); }
        finally
        {
            if (temporary != null) try { temporary.deleteIfExists(); } catch (IOException ignored) { }
        }
    }
}

