@Getter
@Builder(toBuilder = true)
@AllArgsConstructor
@EqualsAndHashCode
@ToString
public class DisplayConfig {
    public static final Color DEFAULT_MENU_TEXT_COLOR = Color.decode("#ff9040");

    private final Color textColor;
    private final Color backgroundColor;
    private final Color borderColor;
    private final Boolean hidden;
    private final Boolean showLootbeam;
    private final Boolean showValue;
    private final Boolean compact;
    private final Boolean showDespawn;
    private final Boolean notify;
    private final TextAccent textAccent;
    private final Color textAccentColor;
    private final Color lootbeamColor;
    private final FontType fontType;
    private final Color menuTextColor;
    private final Boolean hideOverlay;

    private final Boolean hideMenu;

    private final Boolean highlightTile;
    private final Color tileStrokeColor;
    private final Color tileFillColor;

    private final SoundProvider sound;
    private final Integer menuSort;
    private final BufferedImageProvider icon;

    private final List<Integer> evalTrace;

    public DisplayConfig(Color textColor) {
        this.textColor = textColor;
        backgroundColor = null;
        borderColor = null;
        hidden = false;
        showLootbeam = false;
        showValue = false;
        compact = false;
        showDespawn = false;
        notify = false;
        textAccent = null;
        textAccentColor = null;
        lootbeamColor = null;
        fontType = null;
        menuTextColor = null;
        highlightTile = null;
        tileStrokeColor = null;
        tileFillColor = null;
        hideOverlay = null;
        hideMenu = null;
        sound = null;
        menuSort = null;
        icon = null;
        evalTrace = new ArrayList<>();
    }

    public SoundProvider getSound() {
        return !isHidden() ? sound : null;
    }

    public Color getLootbeamColor() {
        return lootbeamColor != null ? lootbeamColor : textColor;
    }

    public Color getTextColor() {
        return textColor != null ? textColor : Color.WHITE;
    }

    public BufferedImageProvider getIcon() {
        return isCompact() ? new BufferedImageProvider.CurrentItem() : icon;
    }

    public Color getMenuTextColor() {
        if (isHidden()) {
            return DEFAULT_MENU_TEXT_COLOR;
        }
        if (menuTextColor != null) {
            return menuTextColor;
        }
        return textColor != null && !textColor.equals(Color.WHITE) ? textColor : DEFAULT_MENU_TEXT_COLOR;
    }

    public int getMenuSort() {
        return menuSort != null ? menuSort : 0;
    }

    public Font getFont() {
        if (fontType == null || fontType == FontType.NORMAL) {
            return FontManager.getRunescapeSmallFont();
        }
        if (fontType == FontType.LARGER) {
            return FontManager.getRunescapeFont();
        }
        return FontManager.getRunescapeBoldFont();
    }

    public Color getTileStrokeColor() {
        return tileStrokeColor != null ? tileStrokeColor : textColor;
    }

    public boolean isHidden() { return hidden != null && hidden; }
    public boolean isShowLootbeam() { return !isHidden() && showLootbeam != null && showLootbeam; }
    public boolean isShowValue() { return showValue != null && showValue; }
    public boolean isShowDespawn() { return showDespawn != null && showDespawn; }
    public boolean isNotify() { return !isHidden() && notify != null && notify; }
    public boolean isHighlightTile() { return !isHidden() && highlightTile != null && highlightTile; }
    public boolean isHideOverlay() { return isHidden() || (hideOverlay != null && hideOverlay); }

    public boolean isCompact() {
        return compact != null && compact;
    }

    public DisplayConfig merge(DisplayConfig other) {
        var b = toBuilder();
        if (other.textColor != null) { b.textColor(other.textColor); }
        if (other.backgroundColor != null) { b.backgroundColor(other.backgroundColor); }
        if (other.borderColor != null) { b.borderColor(other.borderColor); }
        if (other.hidden != null) { b.hidden(other.hidden); }
        if (other.showLootbeam != null) { b.showLootbeam(other.showLootbeam); }
        if (other.showValue != null) { b.showValue(other.showValue); }
        if (other.compact != null) { b.compact(other.compact); }
        if (other.showDespawn != null) { b.showDespawn(other.showDespawn); }
        if (other.notify != null) { b.notify(other.notify); }
        if (other.textAccent != null) { b.textAccent(other.textAccent); }
        if (other.textAccentColor != null) { b.textAccentColor(other.textAccentColor); }
        if (other.lootbeamColor != null) { b.lootbeamColor(other.lootbeamColor); }
        if (other.fontType != null) { b.fontType(other.fontType); }
        if (other.menuTextColor != null) { b.menuTextColor(other.menuTextColor); }
        if (other.highlightTile != null) { b.highlightTile(other.highlightTile); }
        if (other.tileStrokeColor != null) { b.tileStrokeColor(other.tileStrokeColor); }
        if (other.tileFillColor != null) { b.tileFillColor(other.tileFillColor); }
        if (other.hideOverlay != null) { b.hideOverlay(other.hideOverlay); }

        if (hideMenu == null && other.hideMenu != null) { b.hideMenu(other.hideMenu); }
        if (other.sound != null) { b.sound(other.sound); }
        if (other.menuSort != null) { b.menuSort(other.menuSort); }
        if (other.icon != null) { b.icon(other.icon); }
        return b.build();
    }
}

package com.improvedlooting.rs2f;
import com.improvedlooting.rs2f.ast.Condition;
import lombok.Value;
@Value public class FilterRule { Condition cond; DisplayConfig display; boolean terminal; int sourceLine; }

package com.improvedlooting.rs2f;
import java.util.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import com.improvedlooting.rs2f.lang.*;
import com.improvedlooting.rs2f.model.*;

public final class LootFilter {
 public final List<FilterRule> rules;
 private LootFilter(List<FilterRule> rules) { this.rules=Collections.unmodifiableList(new ArrayList<>(rules)); }
 public static Builder builder() { return new Builder(); }
 public static final class Builder {
  final List<FilterRule> rules=new ArrayList<>();
  public Builder setName(String s) { return this; } public Builder setDescription(String s) { return this; }
  public Builder addRule(FilterRule r) {
   BufferedImageProvider icon=r.getDisplay().getIcon();
   if(icon instanceof BufferedImageProvider.Item) { int id=((BufferedImageProvider.Item)icon).getItemId(); if(id<0 || id>100000) throw new IllegalArgumentException("Invalid item icon ID"); }
   if(icon instanceof BufferedImageProvider.Sprite) { BufferedImageProvider.Sprite sprite=(BufferedImageProvider.Sprite)icon; if(sprite.getSpriteId()<0 || (sprite.getSpriteId()>100000 && sprite.getSpriteId()!=9000000) || sprite.getIndex()<0 || sprite.getIndex()>255) throw new IllegalArgumentException("Invalid sprite icon"); }
   if(rules.size()>=10000) throw new IllegalArgumentException("Too many filter rules"); rules.add(r); return this; }
  public LootFilter build() { return new LootFilter(rules); }
 }
 public DisplayConfig evaluate(ItemFacts item) {
  DisplayConfig display=new DisplayConfig(java.awt.Color.WHITE);
  for(FilterRule rule:rules) {
   if(!rule.getCond().test(null,item)) continue;
   display=display.merge(rule.getDisplay());
   display.getEvalTrace().add(rule.getSourceLine());
   if(rule.isTerminal()) break;
  }
  return display;
 }
 public BufferedImageProvider find(ItemFacts item) {
  DisplayConfig display=evaluate(item);
  return display.isHideOverlay() ? null : display.getIcon();
 }
 public Set<String> files() {
  Set<String> names=new LinkedHashSet<>();
  for(FilterRule r:rules) if(r.getDisplay().getIcon() instanceof BufferedImageProvider.File) names.add(((BufferedImageProvider.File)r.getDisplay().getIcon()).getFilename());
  return names;
 }
 public static int preambleLines() {
  try(InputStream in=LootFilter.class.getResourceAsStream("/com/improvedlooting/preamble.rs2f")) {
   String preamble=new String(in.readAllBytes(),StandardCharsets.UTF_8).replace("\r\n","\n").replace('\r','\n');
   return (int)preamble.chars().filter(c->c=='\n').count()+1;
  } catch(IOException e) { throw new IllegalArgumentException("Cannot load filter constants",e); }
 }
 public static LootFilter compile(String source) {
  if(source==null || source.length()>1000000) throw new IllegalArgumentException("Filter exceeds 1 MB");
  try(InputStream in=LootFilter.class.getResourceAsStream("/com/improvedlooting/preamble.rs2f")) {
   String preamble=new String(in.readAllBytes(),StandardCharsets.UTF_8);
   String text=(preamble+"\n"+source+"\n").replace("\r\n","\n").replace('\r','\n');
   TokenStream tokens=new Preprocessor(new Lexer("imported filter",text).tokenize()).preprocess();

   int depth=0, unary=0;
   for(Token t:tokens.getTokens()) { if(t.is(Token.Type.EXPR_START) && ++depth>64) throw new IllegalArgumentException("Filter nesting exceeds 64"); if(t.is(Token.Type.EXPR_END)) depth--; if(t.is(Token.Type.OP_NOT)) { if(++unary>64) throw new IllegalArgumentException("Excessive negation nesting"); } else if(t.isSemantic()) unary=0; }
   return new Parser(tokens).parse();
  } catch(IOException e) { throw new IllegalArgumentException("Cannot load filter constants",e); }
  catch(RuntimeException e) { throw new IllegalArgumentException("Filter could not be imported: "+e.getMessage(),e); }
 }
}

